type Page = 'dashboard'|'coupang'|'naver-brand'|'accounts'|'comments'|'report';
const NAV: Array<{ id: Page; label: string; icon: string }> = [
  { id:'dashboard',label:'대시보드',icon:'▦' },
  { id:'coupang',label:'쿠팡 파트너스',icon:'◈' },
  { id:'naver-brand',label:'네이버 브랜드 커넥트',icon:'N' },
  { id:'comments',label:'댓글',icon:'◌' },
  { id:'report',label:'성과 리포트',icon:'⌁' },
  { id:'accounts',label:'계정 관리',icon:'◎' },
];

function fmtDate(value?: string) { return value ? new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)) : '-'; }
function fmtNumber(value: number) { return new Intl.NumberFormat('ko-KR').format(value); }
function cleanError(value: unknown) { return String(value).replace(/^(?:Error:\s*)+/,'').replace(/^Error invoking remote method '[^']+': /,'').replace(/^(?:Error:\s*)+/,'').replace(/\n[\s\S]*/,''); }

function StatusBar({ snapshot }: { snapshot: AppSnapshot }) {
  const usage = snapshot.dashboard.usage;
  const codex = snapshot.dashboard.codex;
  const codexTitle = codex.version ? `${codex.message} (${codex.version})` : codex.message;
  return <div className="statusbar" aria-label="자동화 및 Codex 상태">
    <span className={`dot ${snapshot.dashboard.automationRunning ? 'success':'muted'}`} />
    <span>{snapshot.dashboard.automationRunning ? '자동화 실행 중':'자동화 일시정지'}</span>
    <span className="divider" />
    <span>현재 루틴 <strong>{fmtNumber(usage.routineTokens)} tokens</strong></span>
    <span className="divider" />
    <span>{usage.available ? <>주간 잔량 <strong>{usage.weeklyRemainingPercent}%</strong></> : '주간 잔량 확인 불가'}</span>
    {usage.resetsAt && <><span className="divider"/><span>초기화 {fmtDate(usage.resetsAt)}</span></>}
    <span className="status-spacer" />
    {usage.checkedAt && <span className="status-muted">마지막 확인 {fmtDate(usage.checkedAt)}</span>}
    <span className={`codex-install ${codex.installed?'installed':'missing'}`} title={codexTitle} aria-label={codexTitle}>
      <span className={`dot ${codex.installed?'success':'warning'}`} />
      Codex {codex.installed?'설치됨':codex.failure==='NOT_FOUND'?'미설치':'실행 오류'}
    </span>
  </div>;
}

const metricIcon=(title:string)=>({
  '전체 계정':'◎','발행 준비':'✓','설정 필요':'!','누적 게시':'▤','게시 완료':'▤','초안 완료':'✎','경고·반려':'△','실패':'×','대기 작업':'◷',
  '처리 댓글':'◌','답글 완료':'↳','답변 안 함':'–','확인 필요':'!','조회수':'◉','클릭':'↗','주문':'▣','수익':'₩',
} as Record<string,string>)[title]??'·';

type MetricTone='primary'|'success'|'warning'|'danger'|'info';

function Card({ title, value, tone='primary', onClick, ariaLabel }: { title:string; value:string|number; tone?:MetricTone; onClick?:()=>void; ariaLabel?:string }) {
  const content=<><span className="metric-card-title">{title}</span><strong>{value}</strong><i className="metric-card-icon" aria-hidden="true">{metricIcon(title)}</i></>;
  return onClick?<button type="button" className={`metric-card metric-card-button metric-tone-${tone}`} onClick={onClick} aria-label={ariaLabel??`${title} ${value}건 상세 보기`}>{content}</button>
    :<article className={`metric-card metric-tone-${tone}`}>{content}</article>;
}

function PeriodSelector({ preset, customFrom, customTo, onPreset, onCustomFrom, onCustomTo, onApply, error }:{preset:PeriodPreset;customFrom:string;customTo:string;onPreset:(value:PeriodPreset)=>void;onCustomFrom:(value:string)=>void;onCustomTo:(value:string)=>void;onApply?:()=>void;error?:string}) {
  return <div className="period-selector"><div className="period-buttons" role="group" aria-label="조회 기간">{(['today','7d','30d','custom'] as PeriodPreset[]).map(value=><button type="button" key={value} className={preset===value?'active':''} aria-pressed={preset===value} onClick={()=>onPreset(value)}>{value==='custom'?'기간 설정':periodPresetLabel(value)}</button>)}</div>{preset==='custom'&&<div className="custom-period"><Field label="시작일"><input type="date" value={customFrom} onChange={e=>onCustomFrom(e.target.value)}/></Field><span aria-hidden="true">~</span><Field label="종료일"><input type="date" value={customTo} onChange={e=>onCustomTo(e.target.value)}/></Field>{onApply&&<button type="button" className="period-apply" onClick={onApply}>기간 적용</button>}</div>}{error&&<small className="period-error" role="alert">{error}</small>}</div>;
}

function Dashboard({ snapshot, selectedAccountId, onSelectAccount, refresh, liveEvents }: { snapshot:AppSnapshot; selectedAccountId:string; onSelectAccount:(id:string)=>void; refresh:()=>Promise<void>; liveEvents:LiveActivityEvent[] }) {
  const [busy,setBusy]=useState(false);
  const [automationNotice,setAutomationNotice]=useState<{tone:'success'|'warning'|'danger';message:string}>();
  const [publishBusy,setPublishBusy]=useState<SourceType>();
  const [publishNotice,setPublishNotice]=useState<{tone:'success'|'warning'|'danger';message:string}>();
  const [accountTotals,setAccountTotals]=useState<Record<string,DashboardActivitySnapshot['counts']>>({});
  const account=snapshot.accounts.find(item=>item.id===selectedAccountId)??snapshot.accounts[0];
  const accountId=account?.id;
  const accountRevision=snapshot.pipelineRuns.find(run=>run.accountId===accountId)?.updatedAt??'';
  const issueRevision=snapshot.logs.find(log=>log.accountId===accountId)?.createdAt??'';
  useEffect(()=>{if(!accountId)return;let active=true;void window.threadsAuto.dashboard.activity({accountId,from:'1970-01-01T00:00:00.000Z',to:new Date().toISOString(),limit:1}).then(value=>{if(active)setAccountTotals(current=>({...current,[accountId]:value.counts}));}).catch(()=>undefined);return()=>{active=false;};},[accountId,accountRevision,issueRevision]);
  if(!account)return <PageFrame title="대시보드" description="계정별 운영 상태와 Agent 작업을 확인합니다." action={<button onClick={refresh}>새로고침</button>}><section className="panel"><Empty text="계정 관리에서 계정을 먼저 등록하세요."/></section></PageFrame>;
  const runtime=snapshot.accountRuntime[account.id];
  const threadsAuth=threadsAccountAuthLabel(account,Boolean(runtime?.credentials.threads));
  const threadsReady=threadsAuth==='Threads 인증 확인됨';
  const runs=snapshot.pipelineRuns.filter(run=>run.accountId===account.id);
  const activeRun=runs.find(run=>run.status==='RUNNING'||run.status==='QUEUED');
  const accountFeed=liveEvents.filter(event=>event.accountId===account.id);
  const latestJobById=new Map<string,LiveActivityEvent>();
  for(const event of accountFeed)if(event.source==='job'&&event.sourceId&&!latestJobById.has(event.sourceId))latestJobById.set(event.sourceId,event);
  const activeJobEvent=[...latestJobById.values()].find(event=>event.tone==='progress');
  const activeJob=snapshot.runningJobs.find(job=>job.accountId===account.id&&!activeRun?.jobId);
  const pending=snapshot.pendingJobs.filter(job=>job.accountId===account.id);
  const totals=accountTotals[account.id];
  const setAutomation=async(enabled:boolean)=>{
    setBusy(true);setAutomationNotice(undefined);
    try{
      const result=await window.threadsAuto.automation.set(enabled);
      await refresh();
      setAutomationNotice(enabled
        ? {tone:'success',message:`전체 자동화를 시작했습니다. 새 계획 ${result.scheduled}건 · 현재 대기 ${result.pendingJobCount}건입니다.`}
        : {tone:'warning',message:`전체 자동화를 중지하고 예정 작업 ${result.cancelled}건을 취소했습니다.`});
    }catch(error){setAutomationNotice({tone:'danger',message:cleanError(error)});await refresh();}
    finally{setBusy(false);}
  };
  const cancel=async(id:string)=>{setBusy(true);try{await window.threadsAuto.automation.cancel(id);await refresh();}finally{setBusy(false);}};
  const savePromotionType=async(job:JobRecord,sourceType:Exclude<SourceType,'DAILY'>)=>{setBusy(true);try{await window.threadsAuto.automation.updatePromotionType({jobId:job.id,accountId:job.accountId,sourceType});await refresh();}finally{setBusy(false);}};
  const immediateTypes:SourceType[]=['DAILY','YOUTUBE','BLOG','COUPANG','NAVER_BRAND_CONNECT'];
  const immediateSelected=(type:SourceType)=>type==='DAILY'?account.dailyEnabled:Boolean(runtime?.providers.includes(type));
  const immediateMissing=(type:SourceType):string[]=>{
    const expired=(value?:string)=>Boolean(value&&Date.parse(value)<=Date.now());
    const missing=[
      !account.active&&'계정 운영 활성화',
      !account.threadsUserId&&'Threads 계정 연결',
      !runtime?.credentials.threads&&'Threads Access Token',
      account.threadsTokenValid===false&&'유효한 Threads Access Token',
      account.threadsTokenCheckFailedAt&&'Threads 연결 재확인',
      (expired(account.threadsTokenExpiresAt)||expired(account.threadsTokenDataAccessExpiresAt))&&'만료되지 않은 Threads Access Token',
      !account.topic.trim()&&'주제',
      !snapshot.dashboard.codex.installed&&'Codex CLI 설치',
    ].filter((value):value is string=>Boolean(value));
    if(type==='YOUTUBE'){
      if(!runtime?.providerConfiguration?.youtube)missing.push('YouTube 채널');
      if(!runtime?.credentials.youtube)missing.push('YouTube Data API Key');
    }
    if(type==='BLOG'&&!runtime?.providerConfiguration?.blog)missing.push('블로그 주소');
    if(type==='COUPANG'){
      if(runtime?.coupang&&!(runtime.coupang.prepared>0))missing.push('자료 분석과 최종 본문 준비가 완료된 쿠팡 파트너스 상품');
      if(!runtime?.coupang)missing.push('쿠팡 파트너스 운영 방식');
    }
    if(type==='NAVER_BRAND_CONNECT'){
      if(runtime?.naverBrand&&!(runtime.naverBrand.prepared>0))missing.push('자료 분석과 최종 본문 준비가 완료된 네이버 상품');
      if(!runtime?.naverBrand)missing.push('네이버 브랜드 커넥트 사용 설정');
    }
    return [...new Set(missing)];
  };
  const publishNow=async(type:SourceType)=>{
    if(!immediateSelected(type))return;
    const missing=immediateMissing(type);
    if(missing.length){setPublishNotice({tone:'warning',message:`${sourceLabel(type)} 즉시 발행에 필요한 항목: ${missing.join(', ')}`});return;}
    if(!window.confirm(`${account.name} 계정에서 ${sourceLabel(type)} 글 1건을 지금 생성·검수한 뒤 실제 Threads에 발행합니다.\n예약 일정과 별도로 추가 발행됩니다. 계속하시겠습니까?`))return;
    setPublishBusy(type);setPublishNotice(undefined);
    try{
      const run=await window.threadsAuto.content.publishNow(account.id,type);
      await refresh();
      if(run.status==='COMPLETED')setPublishNotice({tone:'success',message:`${sourceLabel(type)} 즉시 발행을 완료했습니다.`});
      else if(run.status==='REJECTED')setPublishNotice({tone:'warning',message:run.message||'Agent 검수에서 발행이 보류되었습니다.'});
      else setPublishNotice({tone:'danger',message:run.errorSummary||run.message||'즉시 발행을 완료하지 못했습니다.'});
    }catch(error){setPublishNotice({tone:'danger',message:cleanError(error)});await refresh();}
    finally{setPublishBusy(undefined);}
  };
  const statusRows=[
    {label:'Threads API',enabled:true,ready:threadsReady,readyText:threadsAuth,missingText:threadsAuth},
    {label:'블로그 자료',enabled:Boolean(runtime?.providers.includes('BLOG')),ready:Boolean(runtime?.providerConfiguration?.blog),readyText:'주소 설정됨',missingText:'필요한 정보 · 블로그 주소'},
    {label:'YouTube 자료',enabled:Boolean(runtime?.providers.includes('YOUTUBE')),ready:Boolean(runtime?.credentials.youtube&&runtime?.providerConfiguration?.youtube),readyText:'채널·API 키 준비',missingText:!runtime?.providerConfiguration?.youtube?'필요한 정보 · YouTube 채널':'필요한 정보 · YouTube API 키'},
    {label:'쿠팡 파트너스 자료',enabled:Boolean(runtime?.providers.includes('COUPANG')),ready:(runtime?.coupang?.prepared??0)>0,readyText:`발행 준비 상품 ${runtime?.coupang?.prepared??0}건`,missingText:(runtime?.coupang?.queued??0)>0?'상품 분석·본문 준비 필요':'발행 준비 상품 없음 · 쿠팡 파트너스 메뉴 확인'},
    {label:'네이버 브랜드 커넥트',enabled:Boolean(runtime?.providers.includes('NAVER_BRAND_CONNECT')),ready:Boolean(runtime?.naverBrand?.ready),readyText:runtime?.naverBrand?.message??'상품 처리 준비',missingText:runtime?.naverBrand?.message??'필요한 정보 · 네이버 브랜드 커넥트 설정'},
  ];
  return <PageFrame title="대시보드" description="선택한 계정의 누적 결과와 현재 운영 상태를 확인합니다." action={<div className="dashboard-account-select"><label htmlFor="dashboard-account">운영 계정</label><select id="dashboard-account" value={account.id} onChange={e=>onSelectAccount(e.target.value)}>{snapshot.accounts.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={refresh}>새로고침</button></div>}>
    <section className="account-context"><div><span className={`dot ${account.active?'success':'muted'}`}/><strong>{account.name}</strong><small>{account.threadsHandle?`@${account.threadsHandle.replace(/^@/,'')}`:'Threads 계정 미등록'}</small></div><div className="source-chips">{accountSources(account,runtime).map(type=><span className="badge" key={type}>{sourceLabel(type)}</span>)}</div><span className={`badge ${account.automationTarget?'success':'muted'}`}>{account.automationTarget?'자동 발행 대상':'초안 전용'}</span></section>
    <section className="immediate-publish-panel" aria-labelledby="immediate-publish-title"><div className="immediate-publish-heading"><div><strong id="immediate-publish-title">즉시 발행</strong><small>선택 계정에서 새 글 1건을 생성·Agent 검수 후 바로 발행합니다.</small></div><span>예약 일정은 유지됩니다.</span></div><div className="immediate-publish-actions">{immediateTypes.map(type=>{const selected=immediateSelected(type);const missing=selected?immediateMissing(type):[];const working=publishBusy===type;const blocked=Boolean(activeRun||activeJob||activeJobEvent||publishBusy);return <button type="button" key={type} className={`${selected?'selected':'unselected'} ${missing.length?'needs-setting':''}`} disabled={!selected||blocked} onClick={()=>void publishNow(type)} title={!selected?'계정에서 선택하지 않은 콘텐츠입니다.':missing.length?`누락: ${missing.join(', ')}`:`${sourceLabel(type)} 글 1건 즉시 발행`}><span>{sourceLabel(type)}</span><strong>{working?'발행 중…':'즉시 발행'}</strong><small>{!selected?'사용 안 함':missing.length?'설정 확인 필요':'발행 가능'}</small></button>;})}</div>{publishNotice&&<div className={`immediate-publish-notice ${publishNotice.tone}`} role={publishNotice.tone==='danger'?'alert':'status'} aria-live="polite">{publishNotice.message}</div>}</section>
    <div className="metrics account-metrics"><Card title="누적 게시" value={totals?.published??0} tone="success"/><Card title="초안 완료" value={totals?.draftCompleted??0} tone="primary"/><Card title="경고·반려" value={totals?.warnings??0} tone="warning"/><Card title="실패" value={totals?.failed??0} tone="danger"/><Card title="대기 작업" value={pending.length} tone="info"/></div>
    <div className="dashboard-grid">
      <section className="panel"><header className="section-heading"><div><h2>운영·API 상태</h2><p>선택한 계정에 저장된 설정만 반영합니다.</p></div><AutomationScheduleButton running={snapshot.dashboard.automationRunning} busy={busy} onToggle={setAutomation}/></header>{automationNotice&&<div className={`schedule-notice ${automationNotice.tone}`} role={automationNotice.tone==='danger'?'alert':'status'} aria-live="polite">{automationNotice.message}</div>}<StatusRow label="계정 운영" tone={account.active?'success':'warning'} text={account.active?'활성':'비활성'}/><StatusRow label="자동 발행 운영" tone={account.automationTarget?(threadsReady?'success':'danger'):'warning'} text={account.automationTarget?(threadsReady?'준비':threadsAuth):'사용 안 함 · 초안 전용'}/>{statusRows.map(status=><StatusRow key={status.label} label={status.label} tone={!status.enabled?'warning':status.ready?'success':'danger'} text={!status.enabled?'사용 안 함':status.ready?status.readyText:status.missingText}/>)}</section>
      <section className={`panel agent-live-card ${activeRun||activeJob||activeJobEvent?'working':''}`}><header className="section-heading"><div><h2>실시간 작업 진행</h2><p>선택한 계정에서 Agent가 수행하는 과정을 즉시 표시합니다.</p></div><span className={`live-indicator ${activeRun||activeJob||activeJobEvent?'active':''}`}><i/> {activeRun||activeJob||activeJobEvent?'LIVE':'대기'}</span></header><div className="live-current" aria-live="polite">{activeRun?<><span className="live-status progress">진행</span><div><strong>{stageLabel(activeRun.stage)}</strong><p>{activeRun.message}</p></div><small>{activeRun.progress}%</small></>:activeJob||activeJobEvent?<><span className="live-status progress">진행</span><div><strong>{activeJob?jobKindLabel(activeJob.kind):activeJobEvent?.label}</strong><p>{activeJob?jobKindMessage(activeJob.kind):activeJobEvent?.message}</p></div></>:<><span className="live-status idle">대기</span><div><strong>현재 실행 중인 작업이 없습니다.</strong><p>새 작업이 시작되면 이곳에 바로 표시됩니다.</p></div></>}</div><div className="live-feed" aria-label="실시간 Agent 진행 기록">{accountFeed.length?accountFeed.slice(0,12).map(event=><div className={`live-feed-row ${event.tone}`} key={event.id}><time>{new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(event.createdAt))}</time><span className={`live-status ${event.tone}`}>{event.status}</span><strong>{event.label}</strong><p>{event.message}</p></div>):<div className="live-feed-empty">현재 세션에서 기록된 진행 내용이 없습니다.</div>}</div>{(activeRun??runs[0])&&<QualityDetails run={(activeRun??runs[0])!}/>}</section>
    </div>
    <SchedulePanel snapshot={snapshot} busy={busy} onCancel={cancel} onSave={savePromotionType}/>
  </PageFrame>;
}

function StatusRow({label,tone,text}:{label:string;tone:'success'|'warning'|'danger';text:string}) { const icon=tone==='success'?'●':'▲'; return <div className="status-row"><span>{label}</span><span className={`text-${tone}`}>{icon} {text}</span></div>; }
function Empty({text}:{text:string}) { return <div className="empty"><span>○</span><p>{text}</p></div>; }
function PageFrame({title,description,action,children}:{title:string;description:string;action?:React.ReactNode;children:React.ReactNode}) { return <><header className="page-header"><div><h1>{title}</h1><p>{description}</p></div>{action&&<div className="header-actions">{action}</div>}</header><div className="page-body">{children}</div></>; }

const sourceLabel=(type:string)=>({DAILY:'일상',BLOG:'블로그',YOUTUBE:'유튜브',COUPANG:'쿠팡 파트너스',NAVER_BRAND_CONNECT:'네이버 브랜드 커넥트'} as Record<string,string>)[type]??type;
const accountSources=(account:Account,runtime:AppSnapshot['accountRuntime'][string])=>[
  account.dailyEnabled&&'DAILY',...(runtime?.providers??[]),
].filter(Boolean) as string[];
const accountReadinessIssues=(account:Account,runtime:AppSnapshot['accountRuntime'][string]):string[]=>[
  !account.threadsUserId&&'Threads 계정 연결',
  account.threadsUserId&&!runtime?.credentials.threads&&'Threads Access Token',
  account.threadsTokenCheckFailedAt&&'Threads 연결 재확인',
  account.threadsTokenValid===false&&'Threads 재인증',
  !account.topic.trim()&&'주제',
  !account.dailyEnabled&&!account.promotionEnabled&&'콘텐츠 성격',
].filter((value):value is string=>Boolean(value));
function Accounts({ accounts, runtime, settings, selectedAccountId, onSelectAccount, refresh }:{accounts:Account[];runtime:AppSnapshot['accountRuntime'];settings:AppSettings;selectedAccountId:string;onSelectAccount:(accountId:string)=>void;refresh:()=>Promise<void>}) {
  const [editing,setEditing]=useState<AccountInput|undefined>();
  const [registering,setRegistering]=useState(false);
  const [showIssues,setShowIssues]=useState(false);
  const [error,setError]=useState('');
  const [notice,setNotice]=useState('');
  const readiness=accounts.map(account=>({account,issues:accountReadinessIssues(account,runtime[account.id])}));
  const readyCount=readiness.filter(item=>item.issues.length===0).length;
  const toggle=async(account:Account)=>{setError('');setNotice('');try{await window.threadsAuto.accounts.save({...account,automationTarget:!account.automationTarget});setNotice('계정 자동화 설정을 변경해 전체 스케줄을 중지했습니다. 대시보드에서 다시 시작하면 최신 저장 정보로 전체 계획을 생성합니다.');await refresh();}catch(e){setError(cleanError(e));}};
  const remove=async(account:Account)=>{if(!window.confirm(`${account.name} 계정을 삭제하시겠습니까?\n연동 설정, 대기 작업과 저장된 계정별 키도 함께 삭제됩니다.`))return;setError('');try{await window.threadsAuto.accounts.delete(account.id);await refresh();}catch(e){setError(cleanError(e));}};
  const openAccount=(accountId:string)=>{onSelectAccount(accountId);window.setTimeout(()=>document.getElementById(`account-settings-${accountId}`)?.scrollIntoView({behavior:'smooth',block:'start'}),0);};
  return <PageFrame title="계정 관리" description="Threads 계정, 콘텐츠 성격과 계정별 API 키를 한곳에서 관리합니다." action={<button className="primary" onClick={()=>setRegistering(true)}>+ Threads 계정 등록</button>}>
    <div className="account-summary"><Card title="전체 계정" value={accounts.length} tone="primary"/><Card title="발행 준비" value={readyCount} tone="success"/><Card title="설정 필요" value={accounts.length-readyCount} tone="danger" onClick={accounts.length-readyCount?()=>setShowIssues(true):undefined} ariaLabel={`설정이 필요한 계정 ${accounts.length-readyCount}개 상세 보기`}/></div>
    {error&&<div className="alert" role="alert">{error}</div>}
    {notice&&<div className="notice" role="status">{notice}</div>}
    {accounts.length?<div className="account-grid">{accounts.map(account=>{const rt=runtime[account.id];const issues=accountReadinessIssues(account,rt);const ready=issues.length===0;const needsAuthentication=issues.some(issue=>issue==='Threads 계정 연결'||issue==='Threads Access Token');const sources=accountSources(account,rt);return <article className="account-card" key={account.id}>
      <header><div><strong>{account.name}</strong><small>{account.threadsHandle?`@${account.threadsHandle.replace(/^@/,'')}`:'Threads 계정 미등록'}</small></div><span className={`badge ${ready?'success':'warning'}`}>{ready?'발행 준비':needsAuthentication?'재인증 필요':'운영정보 필요'}</span></header>
      <div className="source-chips">{sources.length?sources.map(type=><span className="badge" key={type}>{sourceLabel(type)}</span>):<span className="badge muted">성격 미설정</span>}</div>
      <dl className="account-facts"><div><dt>오늘 게시</dt><dd>{rt?.todayPosts??0}</dd></div><div><dt>다음 예정</dt><dd>{fmtDate(rt?.nextRunAt)}</dd></div><div><dt>상태</dt><dd>{rt?.hasError?'오류':account.active?'활성':'비활성'}</dd></div></dl>
      <footer><label className="switch-row"><span>이 계정 자동화 사용</span><span className="switch"><input type="checkbox" checked={account.automationTarget} disabled={!ready} onChange={()=>void toggle(account)} aria-label={`${account.name} 자동화 사용`}/><span/></span></label><div className="actions"><button onClick={()=>openAccount(account.id)}>계정 설정</button><button onClick={()=>setEditing(account)}>운영정보</button><button className="danger-link" onClick={()=>void remove(account)}>삭제</button></div></footer>
    </article>})}</div>:<section className="panel"><Empty text="Threads Access Token을 입력해 첫 계정을 등록하세요."/></section>}
    {accounts.length>0&&<><div className="settings-section-title"><div><h2>계정별 상세 설정</h2><p>계정 성격, 자료 연결과 API 키의 확인·수정·삭제를 처리합니다.</p></div></div><div className="account-settings-list">{accounts.map(account=><div id={`account-settings-${account.id}`} key={account.id}><AccountSettingsCard account={account} onSaved={refresh} defaultOpen={account.id===selectedAccountId}/></div>)}</div></>}
    <AppExecutionSettings value={settings} onSaved={refresh}/>
    {registering&&<ThreadsRegistrationDialog onClose={()=>setRegistering(false)} onRegistered={async(account)=>{onSelectAccount(account.id);await refresh();setRegistering(false);}}/>}
    {editing&&<AccountDialog value={editing} onClose={()=>setEditing(undefined)} onSaved={async()=>{setEditing(undefined);await refresh();}}/>}
    {showIssues&&<AccountIssuesDialog items={readiness.filter(item=>item.issues.length>0)} onClose={()=>setShowIssues(false)} onSettings={accountId=>{setShowIssues(false);openAccount(accountId);}} onOperation={account=>{setShowIssues(false);setEditing(account);}}/>}
  </PageFrame>;
}

function AccountIssuesDialog({items,onClose,onSettings,onOperation}:{items:Array<{account:Account;issues:string[]}>;onClose:()=>void;onSettings:(accountId:string)=>void;onOperation:(account:Account)=>void}){
  const dialogRef=React.useRef<HTMLElement>(null);useDialogKeyboard(dialogRef,onClose);
  return <div className="modal-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onClose();}}><section ref={dialogRef} className="modal small account-issues-modal" role="dialog" aria-modal="true" aria-labelledby="account-issues-title"><header><div><h2 id="account-issues-title">설정이 필요한 계정</h2><p>누락된 항목만 표시합니다. Access Token 원문은 표시하지 않습니다.</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="닫기">×</button></header><div className="modal-body account-issue-list">{items.map(({account,issues})=><article className="account-issue-row" key={account.id}><div><strong>{account.name}</strong><small>{account.threadsHandle?`@${account.threadsHandle.replace(/^@/,'')}`:'Threads 계정 미등록'}</small></div><div className="source-chips">{issues.map(issue=><span className="badge warning" key={issue}>{issue}</span>)}</div><div className="actions"><button onClick={()=>onSettings(account.id)}>계정 설정</button><button onClick={()=>onOperation(account)}>운영정보</button></div></article>)}</div><footer><button onClick={onClose}>닫기</button></footer></section></div>;
}

function ThreadsRegistrationDialog({onClose,onRegistered}:{onClose:()=>void;onRegistered:(account:Account)=>Promise<void>}) {
  const dialogRef=React.useRef<HTMLFormElement>(null); useDialogKeyboard(dialogRef,onClose);
  const [accessToken,setAccessToken]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setSaving(true);try{const account=await window.threadsAuto.accounts.register(accessToken.trim());await onRegistered(account);}catch(err){setError(cleanError(err));}finally{setSaving(false);}};
  return <div className="modal-backdrop" role="presentation"><form ref={dialogRef} className="modal small threads-registration" role="dialog" aria-modal="true" aria-labelledby="threads-registration-title" onSubmit={submit}>
    <header><div><h2 id="threads-registration-title">Threads 계정 등록</h2><p>Meta Developers에서 발급받은 장기 Access Token으로 계정을 확인합니다.</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="닫기">×</button></header>
    <div className="modal-body">{error&&<div className="alert" role="alert">{error}</div>}<Field label="Threads Access Token"><input autoFocus type="password" autoComplete="new-password" required placeholder="장기 Access Token 입력" value={accessToken} onChange={e=>setAccessToken(e.target.value)}/></Field><p className="registration-note">토큰 확인에 성공하면 표시명과 @사용자명이 자동으로 등록됩니다.</p></div>
    <footer><button className="primary" disabled={saving||!accessToken.trim()}>{saving?'Threads 계정을 확인하는 중…':'계정 등록'}</button></footer>
  </form></div>;
}

function AccountDialog({value,onClose,onSaved}:{value:AccountInput;onClose:()=>void;onSaved:()=>Promise<void>}) {
  const dialogRef=React.useRef<HTMLFormElement>(null); useDialogKeyboard(dialogRef,onClose);
  const [form,setForm]=useState({...value,personality:value.personality.trim()||'[표준]',tone:value.tone.trim()||'[표준]'}); const [error,setError]=useState(''); const [saving,setSaving]=useState(false);
  const field=(key:keyof AccountInput,value:unknown)=>setForm(prev=>({...prev,[key]:value}));
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setSaving(true);try{await window.threadsAuto.accounts.save(form);await onSaved();}catch(err){setError(cleanError(err));}finally{setSaving(false);}};
  return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><form ref={dialogRef} className="modal" role="dialog" aria-modal="true" aria-labelledby="account-title" onSubmit={submit}>
    <header><div><h2 id="account-title">운영정보 수정</h2><p>Threads 프로필은 Access Token 검증 결과로만 갱신됩니다. 성격과 말투는 비워 두면 [표준]이 적용됩니다.</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="닫기">×</button></header>
    <div className="modal-body form-grid">{error&&<div className="alert" role="alert">{error}</div>}
      <div className="threads-profile-summary wide"><span>Threads 프로필</span><strong>{form.name}</strong><small>@{form.threadsHandle.replace(/^@/,'')}</small></div>
      <Field label="주제" wide><textarea autoFocus value={form.topic} onChange={e=>field('topic',e.target.value)}/></Field><Field label="성격 (선택)"><textarea placeholder="[표준] 일반적이고 균형 잡힌 성격" value={form.personality} onChange={e=>field('personality',e.target.value)}/></Field><Field label="말투 (선택)"><textarea placeholder="[표준] 정중하고 자연스러운 말투" value={form.tone} onChange={e=>field('tone',e.target.value)}/></Field>
      <Field label="대상 독자 (선택)"><textarea value={form.audience} onChange={e=>field('audience',e.target.value)}/></Field><Field label="금지 주제 (선택)"><textarea value={form.forbiddenTopics} onChange={e=>field('forbiddenTopics',e.target.value)}/></Field><Field label="금지 표현 (선택)"><textarea value={form.forbiddenExpressions} onChange={e=>field('forbiddenExpressions',e.target.value)}/></Field>
      <Field label="일상 비율"><input type="number" min="0" value={form.dailyRatio} onChange={e=>field('dailyRatio',Number(e.target.value))}/></Field><Field label="홍보 비율"><input type="number" min="0" value={form.promotionRatio} onChange={e=>field('promotionRatio',Number(e.target.value))}/></Field>
      <Field label="하루 게시 목표"><input type="number" min="1" max="50" value={form.dailyPostTarget} onChange={e=>field('dailyPostTarget',Number(e.target.value))}/></Field><Field label="댓글 확인 주기"><select value={form.commentIntervalMinutes} onChange={e=>field('commentIntervalMinutes',Number(e.target.value))}><option value="5">5분</option><option value="10">10분</option><option value="30">30분</option><option value="60">1시간</option></select></Field>
      <Field label="운영 시작"><input type="time" value={form.operationStart} onChange={e=>field('operationStart',e.target.value)}/></Field><Field label="운영 종료"><input type="time" value={form.operationEnd} onChange={e=>field('operationEnd',e.target.value)}/></Field>
      <fieldset className="wide"><legend>운영 요일</legend>{['일','월','화','수','목','금','토'].map((label,day)=><label className="check" key={day}><input type="checkbox" checked={form.weekdays.includes(day)} onChange={e=>field('weekdays',e.target.checked?[...form.weekdays,day].sort():form.weekdays.filter(value=>value!==day))}/>{label}</label>)}</fieldset>
      <fieldset className="wide"><legend>상태</legend><label className="check"><input type="checkbox" checked={form.active} onChange={e=>field('active',e.target.checked)}/> 계정 활성</label></fieldset>
      <div className="field wide"><label htmlFor="account-fixed-link">고정 링크</label><div className="inline-field"><label className="check"><input type="checkbox" checked={form.fixedLinkEnabled} onChange={e=>field('fixedLinkEnabled',e.target.checked)}/> 사용</label><input id="account-fixed-link" type="url" placeholder="https://" value={form.fixedLinkUrl} onChange={e=>field('fixedLinkUrl',e.target.value)}/></div></div>
    </div><footer><button type="button" onClick={onClose}>취소</button><button className="primary" disabled={saving}>{saving?'저장 중…':'운영정보 저장'}</button></footer>
  </form></div>;
}

function Field({label,wide,children}:{label:string;wide?:boolean;children:React.ReactNode}) { return <label className={`field ${wide?'wide':''}`}><span>{label}</span>{children}</label>; }

const pipelineStatusLabel=(status:PipelineRunView['status'])=>({QUEUED:'대기',RUNNING:'작업 중',STOPPED:'중지',REJECTED:'품질 반려',FAILED:'오류',COMPLETED:'초안 완료'} as const)[status];
const pipelineStatusTone=(status:PipelineRunView['status'])=>status==='COMPLETED'?'success':status==='FAILED'?'danger':status==='REJECTED'||status==='STOPPED'?'warning':status==='RUNNING'?'working':'muted';
const stageLabel=(stage:PipelineRunView['stage'])=>({QUEUED:'준비',DISCOVER:'자료 탐색',SOURCE:'자료 분석',TOPIC:'주제 선정',WRITER:'본문 작성',REVIEWER:'문체 검수',ORCHESTRATOR:'최종 판단',PUBLISH:'발행',DONE:'완료'} as const)[stage];
const vetoLabel=(veto:string)=>({
  UNSUPPORTED_EPISODE:'근거 없는 일화',INVENTED_DIALOGUE:'만든 대화',SCRIPTED_ARC:'각본 같은 전개',PUNCHLINE_CLOSURE:'억지 마무리',AGE_STEREOTYPE:'연령 고정관념',
  AI_ABSTRACT_LEXICON:'AI식 추상 어휘',
  AWKWARD_COLLOQUIAL_WORDING:'어색한 구어 표현',
  LOW_RESONANCE:'공감·생활감 부족',NO_PUBLISH_VALUE:'게시 가치 부족',
  CONTRIVED_SCENARIO:'억지로 만든 생활 장면',EMPTY_CONTRAST:'의미 없는 불편 대조',
  PROMO_BROCHURE_CTA:'홍보 문구·행동 유도',MECHANICAL_ENUMERATION:'기계적 나열',SOURCE_OUTLINE_REPACKAGING:'원문 목차식 재구성',ABSTRACT_REPORT_STYLE:'추상적 보고서 문체',
  REDUNDANT_SUMMARY:'반복 요약',UNSUPPORTED_CLAIM:'근거 없는 주장',INVENTED_EXPERIENCE:'만든 체험',HEDGED_RECOMMENDATION:'장점을 흐린 추천',
} as Record<string,string>)[veto]??veto;
const workflowStages=(run:PipelineRunView):PipelineRunView['stage'][]=>run.mode==='PUBLISH'?['DISCOVER','SOURCE','TOPIC','WRITER','REVIEWER','ORCHESTRATOR','PUBLISH','DONE']:['DISCOVER','SOURCE','TOPIC','WRITER','REVIEWER','ORCHESTRATOR','DONE'];
const jobKindLabel=(kind:AppSnapshot['runningJobs'][number]['kind'])=>({PUBLISH:'게시 생성·발행',COMMENTS:'댓글 확인·답변',INSIGHTS:'Threads 성과 수집',COUPANG_REPORT:'쿠팡 파트너스 성과 수집'} as const)[kind];
const jobKindMessage=(kind:AppSnapshot['runningJobs'][number]['kind'])=>({PUBLISH:'게시할 자료와 본문을 처리하고 있습니다.',COMMENTS:'미처리 댓글을 확인하고 답변 여부를 판단하고 있습니다.',INSIGHTS:'게시물별 조회·반응 지표를 수집하고 있습니다.',COUPANG_REPORT:'클릭·주문·수익 지표를 수집하고 있습니다.'} as const)[kind];

function QualityDetails({run}:{run:PipelineRunView}) {
  return <details className="quality-detail"><summary>진행·품질판정 상세 · {fmtDate(run.updatedAt)}</summary><div className="pipeline-steps">{workflowStages(run).map((stage,index)=><div className={`pipeline-step ${run.stage===stage?'current':''}`} key={stage}><span>{index+1}</span><small>{stageLabel(stage)}</small></div>)}</div><div className="quality-decisions">{run.quality.length?run.quality.map((decision,index)=><article key={index}><header><strong>{decision.stage==='REVIEWER'?'문체 검수':decision.stage==='ORCHESTRATOR'?'최종 판단':'규칙 검증'}</strong><span className={`badge ${decision.decision==='PASS'?'success':'danger'}`}>{decision.decision==='PASS'?'통과':'반려'}</span></header><p>{decision.reason}</p>{decision.vetoes.length>0&&<small>{decision.vetoes.map(vetoLabel).join(' · ')}</small>}</article>):<p>아직 품질판정 내역이 없습니다.</p>}</div></details>;
}

function ActivityRow({run,snapshot,expanded=false,onComments,onOpen,onDelete,deleting=false,deleted=false}:{run:PipelineRunView;snapshot:AppSnapshot;expanded?:boolean;onComments?:(accountId:string,postId:string)=>void;onOpen?:(run:PipelineRunView)=>void;onDelete?:(run:PipelineRunView)=>void;deleting?:boolean;deleted?:boolean}) {
  const account=snapshot.accounts.find(item=>item.id===run.accountId);
  const post=snapshot.dashboard.recentPosts.find(item=>item.id===run.postId);
  const published=run.mode==='PUBLISH'&&run.status==='COMPLETED';
  const removed=Boolean(deleted||run.postDeletedAt||post?.remoteDeletedAt);
  const label=removed?'게시 후 삭제':published?'게시 성공':pipelineStatusLabel(run.status);
  const tone=removed?'muted':published?'success':pipelineStatusTone(run.status);
  const problem=run.errorSummary??(run.status==='REJECTED'||run.status==='STOPPED'?run.message:undefined);
  const diagnostics=snapshot.logs.filter(log=>log.runId===run.id&&(log.level==='WARN'||log.level==='ERROR'));
  const fullBody=post?.body??run.draftBody;
  return <details className={`activity-row ${tone}`} open={expanded&&Boolean(problem)}><summary><span className={`badge ${tone}`}>{label}</span><strong>{account?.name??'삭제된 계정'}</strong><span className="badge muted">{sourceLabel(run.source?.sourceType??post?.sourceType??'DAILY')}</span><p>{run.draftBody??run.source?.title??run.message}</p><span className="activity-date"><time>{fmtDate(run.finishedAt??run.updatedAt)}</time>{published&&run.threadsPostId&&onComments&&<button type="button" className="badge muted comment-count" title="앱이 수집한 댓글입니다. Threads 전체 댓글 수와 다를 수 있습니다." onClick={event=>{event.preventDefault();event.stopPropagation();onComments(run.accountId,run.threadsPostId!);}}>수집 댓글 {run.collectedCommentCount??0}</button>}</span><span className="activity-expand">{problem?'상세':'보기'}</span></summary><div className="activity-detail"><div><span>현재 단계</span><strong>{stageLabel(run.stage)}</strong></div><div><span>작업 유형</span><strong>{run.mode==='PUBLISH'?'자동 발행':'미게시 초안'}</strong></div>{post?.threadsPostId&&<div><span>Threads ID</span><strong className="mono">{post.threadsPostId}</strong></div>}{fullBody&&<div className="wide activity-generated-copy"><span>생성된 문장</span><p>{fullBody}</p></div>}{problem&&<div className="wide"><span>원인</span><strong>{problem}</strong></div>}<div className="wide"><QualityDetails run={run}/></div>{diagnostics.map(log=><div className="wide diagnostic-line" key={log.id}><span>{fmtDate(log.createdAt)} · {log.stage?stageLabel(log.stage):log.category}</span><strong>{log.diagnosticSummary??log.message}</strong></div>)}{onOpen&&<button className="history-detail-button" onClick={()=>onOpen(run)}>상세 창 열기</button>}{onDelete&&published&&run.postId&&!removed&&<button className="danger-button" disabled={deleting} onClick={()=>onDelete(run)}>{deleting?'삭제 확인 중…':'Threads 본문 삭제'}</button>}<small className="activity-run-id">진단 ID {run.id}</small></div></details>;
}

function OperationalIssueRow({log,snapshot}:{log:AppSnapshot['logs'][number];snapshot:AppSnapshot}) {
  const account=snapshot.accounts.find(item=>item.id===log.accountId);
  return <details className="activity-row danger"><summary><span className="badge danger">운영 오류</span><strong>{account?.name??'삭제된 계정'}</strong><span className="badge muted">{sourceLabel(log.category)}</span><p>{log.message}</p><time>{fmtDate(log.createdAt)}</time><span className="activity-expand">상세</span></summary><div className="activity-detail"><div className="wide diagnostic-line"><span>원인</span><strong>{log.diagnosticSummary??log.message}</strong></div><small className="activity-run-id">진단 ID LOG-{log.id}</small></div></details>;
}

const commentDecisionLabel=(value:CommentRecord['decision'])=>({PENDING:'판단 대기',REPLIED:'답글 완료',SKIPPED:'답변 안 함',REPLY_UNCERTAIN:'확인 필요',FAILED_RETRYABLE:'재시도 대기'} as const)[value];
function Comments({snapshot,accountId,onSelectAccount,postId,onClearPostFilter}:{snapshot:AppSnapshot;accountId:string;onSelectAccount:(id:string)=>void;postId?:string;onClearPostFilter:()=>void}){
  const emptySummary:CommentSummary={total:0,pending:0,replied:0,skipped:0,attentionNeeded:0};
  const [items,setItems]=useState<CommentRecord[]>([]);const [summary,setSummary]=useState<CommentSummary>(emptySummary);const [loading,setLoading]=useState(false);const [error,setError]=useState('');
  const load=async()=>{if(!accountId)return;setLoading(true);setError('');try{const value=await window.threadsAuto.comments.list(accountId,100,postId);setItems(value.items);setSummary(value.summary);}catch(e){setError(cleanError(e));}finally{setLoading(false);}};
  useEffect(()=>{if(!accountId)return;let active=true;void window.threadsAuto.comments.list(accountId,100,postId).then(value=>{if(!active)return;setItems(value.items);setSummary(value.summary);setError('');}).catch(e=>{if(active)setError(cleanError(e));});return()=>{active=false;};},[accountId,postId]);
  const removeReply=async(item:CommentRecord)=>{if(!item.replyId||!window.confirm('프로그램이 작성한 이 답글을 Threads에서 삭제하시겠습니까?\n다른 사용자의 원댓글은 삭제하지 않습니다.'))return;setLoading(true);setError('');try{await window.threadsAuto.threadsContent.deleteReply(accountId,item.id);await load();}catch(e){setError(cleanError(e));setLoading(false);}};
  return <PageFrame title="댓글" description="다른 사용자의 댓글과 Agent 판단, 프로그램이 작성한 답글 이력을 계정별로 확인합니다." action={<div className="dashboard-account-select"><label htmlFor="comment-account">계정</label><select id="comment-account" value={accountId} onChange={e=>onSelectAccount(e.target.value)}>{snapshot.accounts.map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select><button disabled={loading} onClick={()=>void load()}>{loading?'확인 중…':'새로고침'}</button></div>}>
    {postId&&<div className="notice">선택 게시물의 수집 댓글 <button onClick={onClearPostFilter}>전체 댓글 보기</button></div>}<div className="comment-summary"><Card title="처리 댓글" value={summary.total} tone="primary"/><Card title="답글 완료" value={summary.replied} tone="success"/><Card title="답변 안 함" value={summary.skipped} tone="warning"/><Card title="확인 필요" value={summary.attentionNeeded} tone="danger"/></div>{error&&<div className="alert">{error}</div>}
    <section className="panel no-padding">{items.length?<div className="comment-list">{items.map(item=><details className="comment-row" key={item.id}><summary><span className={`badge ${item.replyDeletedAt||item.replyStatus==='DELETED'?'muted':item.decision==='REPLIED'?'success':item.decision.includes('UNCERTAIN')||item.decision.includes('FAILED')?'danger':'muted'}`}>{item.replyDeletedAt||item.replyStatus==='DELETED'?'게시 후 삭제':commentDecisionLabel(item.decision)}</span><strong>@{item.authorUsername||'알 수 없음'}</strong><div className="comment-context"><small>원글 · {item.postBody||`Threads 게시물 ${item.postId}`}</small><p>{item.body}</p></div><time>{fmtDate(item.commentedAt??item.createdAt)}</time><span className="activity-expand">상세</span></summary><div className="comment-detail"><div className="comment-parent"><span>원본 게시물 · {fmtDate(item.postPublishedAt)}</span><p>{item.postBody||"앱에 저장되지 않은 게시물입니다."}</p><small>Threads 게시물 ID: {item.postId}</small></div><div><span>원댓글</span><p>{item.body}</p></div><div><span>Agent 판단</span><p>{item.decisionReason||commentDecisionLabel(item.decision)}</p></div>{item.replyBody&&<div><span>작성한 답글</span><p>{item.replyBody}</p><small>{item.replyDeletedAt||item.replyStatus==='DELETED'?'게시 후 삭제':item.replyStatus==='DELETE_FAILED'?'삭제 실패':item.replyStatus==='UNCERTAIN'?'게시 확인 필요':'게시됨'} · {fmtDate(item.repliedAt)}</small></div>}{item.lastError&&<div className="alert">{item.lastError}</div>}{item.replyId&&!item.replyDeletedAt&&item.replyStatus!=='DELETED'&&<button className="danger-button" disabled={loading} onClick={()=>void removeReply(item)}>내가 작성한 답글 삭제</button>}</div></details>)}</div>:<Empty text={loading?'댓글 이력을 불러오고 있습니다.':postId?'이 게시물에서 수집한 댓글이 없습니다.':'이 계정의 처리된 댓글 이력이 없습니다.'}/>}</section>
  </PageFrame>;
}

function Report({snapshot,refresh,onComments}:{snapshot:AppSnapshot;refresh:()=>Promise<void>;onComments:(accountId:string,postId:string)=>void}) {
  const accounts=snapshot.accounts;
  const [view,setView]=useState<'processing'|'performance'>('processing');
  const [selected,setSelected]=useState<string[]>(()=>accounts.map(account=>account.id));
  const initialCustom=useMemo(()=>defaultCustomPeriod(),[]);
  const [range,setRange]=useState<PeriodPreset>('7d');
  const [customFrom,setCustomFrom]=useState(initialCustom.from);
  const [customTo,setCustomTo]=useState(initialCustom.to);
  const [rows,setRows]=useState<ReportRow[]>([]);
  const [coupangRows,setCoupangRows]=useState<AffiliateReportRow[]>([]);
  const [activity,setActivity]=useState<DashboardActivitySnapshot>({counts:{published:0,draftCompleted:0,warnings:0,failed:0},runs:[],operationalIssues:[]});
  const [loading,setLoading]=useState(false);
  const [queried,setQueried]=useState(false);
  const [error,setError]=useState('');
  const [notice,setNotice]=useState('');
  const [deletingRunId,setDeletingRunId]=useState<string>();
  const [deletedRunIds,setDeletedRunIds]=useState<Set<string>>(()=>new Set());
  const changeView=(next:'processing'|'performance')=>{setView(next);setQueried(false);setError('');};
  const query=async()=>{setLoading(true);setError('');setNotice('');try{const period=resolvePeriodRange(range,customFrom,customTo);if(view==='processing'){const results=await Promise.all(selected.map(accountId=>window.threadsAuto.dashboard.activity({accountId,...period,limit:50})));setActivity({counts:results.reduce((total,result)=>({published:total.published+result.counts.published,draftCompleted:total.draftCompleted+result.counts.draftCompleted,warnings:total.warnings+result.counts.warnings,failed:total.failed+result.counts.failed}),{published:0,draftCompleted:0,warnings:0,failed:0}),runs:results.flatMap(result=>result.runs).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,100),operationalIssues:results.flatMap(result=>result.operationalIssues).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,100)});}else{const result=await window.threadsAuto.reports.query({accountIds:selected,...period});setRows(result.posts);setCoupangRows(result.coupang);if(result.warnings.length)setNotice(result.warnings.join(' '));}setQueried(true);}catch(e){setError(cleanError(e));}finally{setLoading(false);}};
  const removePublishedPost=async(run:PipelineRunView)=>{if(!run.postId)return;setError('');setNotice('');try{const post=await window.threadsAuto.content.post(run.accountId,run.postId);if(!post?.threadsPostId)throw new Error('삭제할 Threads 게시물을 찾지 못했습니다.');const warning=post.sourceType==='COUPANG'&&post.coupangReplyId?'이전 방식 쿠팡 파트너스 안내 댓글을 먼저 삭제한 뒤 상품 본문을 삭제합니다.\n두 항목은 되돌릴 수 없습니다. 계속하시겠습니까?':'이 계정이 직접 작성한 Threads 본문을 삭제하시겠습니까?\n삭제한 본문은 되돌릴 수 없습니다.';if(!window.confirm(warning))return;setDeletingRunId(run.id);await window.threadsAuto.threadsContent.deletePost(run.accountId,post.id);setDeletedRunIds(current=>new Set(current).add(run.id));setNotice('Threads 본문 삭제를 확인했습니다.');await refresh();}catch(e){setError(cleanError(e));}finally{setDeletingRunId(undefined);}};
  const coupangSubtotals=useMemo(()=>{const grouped=new Map<string,{connectionId:string;keyLabel:string;accountNames:string[];clicks:number;orders:number;orderAmount:number;revenue:number}>();for(const row of coupangRows){const total=grouped.get(row.connectionId)??{connectionId:row.connectionId,keyLabel:row.keyLabel,accountNames:row.accountNames,clicks:0,orders:0,orderAmount:0,revenue:0};total.clicks+=row.clicks;total.orders+=row.orders;total.orderAmount+=row.orderAmount;total.revenue+=row.revenue;grouped.set(row.connectionId,total);}return [...grouped.values()].sort((a,b)=>a.keyLabel.localeCompare(b.keyLabel,'ko-KR'));},[coupangRows]);
  const totals=useMemo(()=>({views:rows.reduce((total,row)=>total+row.views,0),...coupangSubtotals.reduce((total,row)=>({clicks:total.clicks+row.clicks,orders:total.orders+row.orders,orderAmount:total.orderAmount+row.orderAmount,revenue:total.revenue+row.revenue}),{clicks:0,orders:0,orderAmount:0,revenue:0})}),[rows,coupangSubtotals]);
  const periodLabel=periodPresetLabel(range);
  return <PageFrame title="리포트" description={view==='processing'?'기간별 처리 결과와 실패 원인을 조회합니다.':'게시 후 성과 지표를 기간과 계정별로 조회합니다.'} action={<button className="primary" disabled={loading||!selected.length} onClick={()=>void query()}>{loading?'조회 중…':'조회'}</button>}>
    <div className="content-view-tabs report-view-tabs" role="tablist" aria-label="리포트 종류"><button role="tab" aria-selected={view==='processing'} className={view==='processing'?'active':''} onClick={()=>changeView('processing')}>처리 현황</button><button role="tab" aria-selected={view==='performance'} className={view==='performance'?'active':''} onClick={()=>changeView('performance')}>성과 분석</button></div>
    <section className="panel filters"><div><strong>조회 기간</strong><PeriodSelector preset={range} customFrom={customFrom} customTo={customTo} onPreset={setRange} onCustomFrom={setCustomFrom} onCustomTo={setCustomTo}/></div><fieldset><legend>조회 계정</legend><div className="account-checks">{accounts.map(a=><label className="check" key={a.id}><input type="checkbox" checked={selected.includes(a.id)} onChange={e=>setSelected(prev=>e.target.checked?[...prev,a.id]:prev.filter(id=>id!==a.id))}/>{a.name}</label>)}</div></fieldset></section>
    {notice&&<div className="notice" role="status">{notice}</div>}{error&&<div className="alert" role="alert">{error}</div>}
    {view==='processing'?<>
      <div className="metrics report-metrics"><Card title="게시 완료" value={activity.counts.published} tone="success"/><Card title="초안 완료" value={activity.counts.draftCompleted} tone="primary"/><Card title="경고·반려" value={activity.counts.warnings} tone="warning"/><Card title="실패" value={activity.counts.failed} tone="danger"/></div>
      <section className="panel no-padding"><header className="result-header"><div><h2>{periodLabel} 처리 이력</h2><p>계정별 작업 결과와 실패 원인을 함께 확인할 수 있습니다.</p></div></header>{activity.runs.length||activity.operationalIssues.length?<div className="result-list">{chronologicalHistory(activity.runs,activity.operationalIssues).map(item=>item.kind==='log'?<OperationalIssueRow key={item.key} log={item.log} snapshot={snapshot}/>:<ActivityRow key={item.key} run={item.run} snapshot={snapshot} onComments={onComments} onDelete={removePublishedPost} deleting={deletingRunId===item.run.id} deleted={deletedRunIds.has(item.run.id)}/>)}</div>:<Empty text={queried?'선택한 기간에 처리 이력이 없습니다.':'기간과 계정을 선택한 뒤 조회하세요.'}/>}</section>
    </>:<>
      <div className="metrics report-metrics"><Card title="Threads 조회수" value={fmtNumber(totals.views)} tone="primary"/><Card title="쿠팡 파트너스 클릭 집계" value={fmtNumber(totals.clicks)} tone="info"/><Card title="쿠팡 파트너스 구매 수량 집계" value={fmtNumber(totals.orders)} tone="warning"/><Card title="쿠팡 파트너스 수익 집계" value={`${fmtNumber(totals.revenue)}원`} tone="success"/></div>
      <section className="panel no-padding"><header className="result-header"><div><h2>쿠팡 파트너스 키별 소계</h2><p>동일한 API 키는 한 번만 조회하며, 계정 설정에 입력한 키 구분명으로 합산합니다.</p></div></header>{coupangSubtotals.length?<div className="table-wrap"><table><thead><tr><th>키 구분명</th><th>연결된 Threads 계정</th><th>클릭</th><th>구매 수량</th><th>구매 금액</th><th>수익</th></tr></thead><tbody>{coupangSubtotals.map(r=><tr key={r.connectionId}><td><strong>{r.keyLabel}</strong></td><td>{r.accountNames.join(', ')}</td><td>{fmtNumber(r.clicks)}</td><td>{fmtNumber(r.orders)}</td><td>{fmtNumber(r.orderAmount)}원</td><td>{fmtNumber(r.revenue)}원</td></tr>)}</tbody></table></div>:<Empty text={queried?'선택한 기간의 쿠팡 파트너스 성과가 없습니다.':'조회하면 쿠팡 파트너스 최신 성과를 함께 가져옵니다.'}/>}</section>
      {coupangRows.length>0&&<section className="panel no-padding"><header className="result-header"><div><h2>쿠팡 파트너스 일별 내역</h2><p>Open API가 제공하는 클릭·구매 수량·구매 금액·수익만 표시합니다.</p></div></header><div className="table-wrap"><table><thead><tr><th>키 구분명</th><th>날짜</th><th>클릭</th><th>구매 수량</th><th>구매 금액</th><th>수익</th></tr></thead><tbody>{coupangRows.map(r=><tr key={`${r.connectionId}:${r.date}`}><td>{r.keyLabel}</td><td>{r.date}</td><td>{fmtNumber(r.clicks)}</td><td>{fmtNumber(r.orders)}</td><td>{fmtNumber(r.orderAmount)}원</td><td>{fmtNumber(r.revenue)}원</td></tr>)}</tbody></table></div></section>}
      <section className="panel no-padding"><header className="result-header"><div><h2>Threads 게시물 성과</h2><p>행 또는 본문 보기를 누르면 등록된 글을 확인할 수 있습니다.</p></div></header>{rows.length?<PostPerformanceTable rows={rows} formatDate={fmtDate} formatNumber={fmtNumber}/>:<Empty text={queried?'선택한 기간에 게시물 성과가 없습니다.':'기간과 계정을 선택한 뒤 조회하세요.'}/>}</section>
    </>}
  </PageFrame>;
}

type CredentialState=Record<string,{stored:boolean;updatedAt?:string}>;
const scopedKey=(name:'threadsToken'|'youtubeApiKey'|'coupangAccessKey'|'coupangSecretKey',accountId:string)=>`${name}:${accountId}` as CredentialKey;

function SecretControl({label,credentialKey,value,status,onChange,onDelete}:{label:string;credentialKey:CredentialKey;value:string;status?:{stored:boolean;updatedAt?:string};onChange:(value:string)=>void;onDelete:()=>void}) {
  return <div className="secret-control" data-credential={credentialKey}><div className="secret-label"><span>{label}</span>{!credentialKey.startsWith('threadsToken:')&&<small>{status?.stored?`저장됨 · ${fmtDate(status.updatedAt)}`:'저장되지 않음'}</small>}</div><div className="secret-input"><input aria-label={label} type="password" autoComplete="new-password" value={value} placeholder={status?.stored?'•••••••• 새 값으로 교체':'값 입력'} onChange={e=>onChange(e.target.value)}/>{status?.stored&&<button type="button" className="danger-link" onClick={onDelete}>삭제</button>}</div></div>;
}

function ThreadsTokenExpiry({accountId,status,busy,message,onRefresh}:{accountId:string;status:ThreadsTokenStatus;busy:boolean;message:string;onRefresh:()=>void}) {
  const fallback=tokenExpiryView(status.expiresAt);const tone:TokenExpiryTone=status.state==='INVALID'||status.state==='EXPIRED'||(typeof status.daysRemaining==='number'&&status.daysRemaining<=7)?'danger':status.state==='EXPIRING'||status.missingScopes.length>0||!status.fresh?'warning':status.state==='ACTIVE'?'success':fallback.tone;
  const titleId=`threads-token-expiry-title-${accountId}`,statusId=`threads-token-refresh-status-${accountId}`;
  const label=status.state==='CHECK_FAILED'?'확인 실패':status.stored?(status.state==='INVALID'?'유효하지 않은 토큰':typeof status.daysRemaining==='number'?(status.state==='EXPIRED'?'토큰 만료':status.daysRemaining===0?'오늘 만료':`${status.estimated?'약 ':''}${status.daysRemaining}일 남음`):fallback.label):'토큰 없음';
  const showRefresh=shouldShowTokenRefresh(status);
  const scopeText=status.state==='INVALID'||status.state==='EXPIRED'?'새 토큰으로 권한을 다시 확인해야 합니다.':status.state==='CHECK_FAILED'?'권한 상태를 다시 확인해야 합니다.':!status.stored?'토큰을 저장하면 권한 정보를 다시 확인합니다.':status.missingScopes.length?`권한 부족 · 누락: ${status.missingScopes.join(', ')}`:status.scopes.length?`필수 권한 정상${status.scopes.includes('threads_delete')?' · 삭제 포함':''}`:'권한 정보를 확인하지 못했습니다.';
  const statusDetail=status.state==='CHECK_FAILED'?status.message:status.estimated?'Meta 토큰 디버거에서 확인하지 못해 저장 시각 기준 예상 정보를 표시합니다.':status.checkedAt?(status.warning??'마지막으로 확인한 토큰 정보입니다.'):'토큰 상세 정보를 아직 확인하지 못했습니다.';
  return <section className={`token-expiry ${status.stored?tone:'muted'}${showRefresh?'':' no-action'}`} aria-labelledby={titleId}><div className="token-expiry-copy"><span id={titleId}>토큰 상태</span><strong>{label}</strong><small>{status.stored?statusDetail:'Access Token을 저장하고 연결을 확인하세요.'}</small></div><dl><div><dt>발급일{status.estimated?'(추정)':''}</dt><dd>{status.issuedAt?fmtDate(status.issuedAt):'확인되지 않음'}</dd></div><div><dt>{status.estimated?'예상 만료일':'만료일'}</dt><dd>{status.expiresAt?fmtDate(status.expiresAt):'확인되지 않음'}</dd></div><div><dt>데이터 접근 만료</dt><dd>{status.dataAccessExpiresAt?fmtDate(status.dataAccessExpiresAt):'확인되지 않음'}</dd></div><div><dt>최근 토큰 확인</dt><dd>{status.checkedAt?fmtDate(status.checkedAt):'확인하지 못함'}</dd></div></dl>{showRefresh&&<button type="button" className="token-refresh-button" disabled={busy} aria-describedby={statusId} onClick={onRefresh}>{busy?'연장 중…':'토큰 연장'}</button>}<span className={`token-scope-summary ${status.state==='CHECK_FAILED'||status.state==='INVALID'||status.state==='EXPIRED'||status.missingScopes.length?'missing':''}`}>{scopeText}</span><span id={statusId} className="token-refresh-status" role="status" aria-live="polite">{message}</span></section>;
}

type CoupangMode='MANUAL_LINKS'|'OPEN_API';
type CoupangQueueItem=CoupangProductQueueItem;
type CoupangQueueApi={
  list:(accountId:string)=>Promise<CoupangQueueItem[]|{items:CoupangQueueItem[]}>;
  add:(input:{accountId:string;text:string})=>Promise<unknown>;
  update:(input:{accountId:string;id:string;productName:string;productNote:string})=>Promise<unknown>;
  updateDraft:(input:{accountId:string;id:string;body:string;expectedUpdatedAt:string})=>Promise<CoupangQueueItem>;
  removeImage:(input:{accountId:string;id:string;imageUrl:string;expectedUpdatedAt:string})=>Promise<CoupangQueueItem>;
  delete:(input:{accountId:string;id:string})=>Promise<unknown>;
  prepare:(input:{accountId:string;id:string})=>Promise<unknown>;
  prepareMany:(input:{accountId:string;ids:string[]})=>Promise<{prepared:string[];failed:Array<{id:string;message:string}>}>;
  retry:(input:{accountId:string;id:string})=>Promise<unknown>;
};

const coupangQueueApi=()=>{
  const api=(window.threadsAuto as unknown as {coupangQueue?:CoupangQueueApi}).coupangQueue;
  if(!api)throw new Error('쿠팡 파트너스 수동 링크 기능을 불러오지 못했습니다. 프로그램을 다시 시작하세요.');
  return api;
};
type NaverBrandQueueApi=Pick<CoupangQueueApi,'list'|'add'|'updateDraft'|'removeImage'|'delete'|'prepare'|'retry'>;
const naverBrandQueueApi=()=>{
  const api=(window.threadsAuto as unknown as {naverBrandQueue?:NaverBrandQueueApi}).naverBrandQueue;
  if(!api)throw new Error('네이버 브랜드 커넥트 기능을 불러오지 못했습니다. 프로그램을 다시 시작하세요.');
  return api;
};
const normalizeCoupangQueue=(value:CoupangQueueItem[]|{items:CoupangQueueItem[]})=>Array.isArray(value)?value:value.items;
const coupangQueueStatusLabel=(status:string)=>({QUEUED:'준비 대기',PROCESSING:'이미지·최종 본문 준비 중',PREVIEW_READY:'발행 준비 완료',REVIEW_REQUIRED:'검토 필요',COMPLETED:'발행 완료',FAILED:'준비 실패',INFORMATION_REQUIRED:'상품 정보 필요'} as Record<string,string>)[status]??status;
const coupangQueueTone=(item:CoupangQueueItem)=>item.metadataStatus==='INFORMATION_REQUIRED'||item.status==='INFORMATION_REQUIRED'?'warning':item.status==='FAILED'?'queue-failed':item.status==='COMPLETED'?'success':item.status==='PROCESSING'?'progress':item.status==='PREVIEW_READY'?'success':item.status==='REVIEW_REQUIRED'?'warning':'queue-waiting';
const coupangFactsText=(facts:unknown)=>{
  if(typeof facts==='string')return facts;
  if(Array.isArray(facts))return facts.slice(0,3).map(value=>typeof value==='string'?value:JSON.stringify(value)).join(' · ');
  if(facts&&typeof facts==='object')return Object.entries(facts as Record<string,unknown>).slice(0,3).map(([key,value])=>`${key}: ${String(value)}`).join(' · ');
  return '';
};

function ProviderHeading({icon,title,description}:{icon:string;title:string;description:string}) {
  return <div className="provider-heading"><span className="provider-icon" aria-hidden="true">{icon}</span><div><h3>{title}</h3><p>{description}</p></div></div>;
}

function CoupangSearchOptions({value,onChange}:{value:CoupangProductSearchSettings;onChange:(value:CoupangProductSearchSettings)=>void}) {
  const patch=<K extends keyof CoupangProductSearchSettings>(key:K,next:CoupangProductSearchSettings[K])=>onChange({...value,[key]:next});
  return <div className="coupang-search-options">
    <Field label="검색 키워드"><textarea rows={3} value={value.keywords} placeholder="예: 개발자 책상, 사무용품, 생활용품" onChange={event=>patch('keywords',event.target.value)}/><small>여러 키워드는 쉼표로 구분합니다. 키워드 검색은 단어별 상위 10개를 가져옵니다.</small></Field>
    <fieldset className="coupang-source-options"><legend>상품 가져오기 경로 · 선택 항목을 모두 포함</legend>
      <label className="check"><input type="checkbox" checked={value.keywordSearchIncluded} onChange={event=>patch('keywordSearchIncluded',event.target.checked)}/> 키워드 검색 포함</label>
      <label className="check"><input type="checkbox" checked={value.goldBoxIncluded} onChange={event=>patch('goldBoxIncluded',event.target.checked)}/> 골드박스 포함 <strong>(키워드 무시)</strong></label>
      <div className="coupang-source-row"><label className="check"><input type="checkbox" checked={value.categoryBestIncluded} onChange={event=>patch('categoryBestIncluded',event.target.checked)}/> 카테고리 베스트 포함</label><select aria-label="카테고리" value={value.categoryId} disabled={!value.categoryBestIncluded} onChange={event=>patch('categoryId',event.target.value as CoupangProductSearchSettings['categoryId'])}><option value="ALL">전체</option>{COUPANG_CATEGORY_OPTIONS.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></div>
      <div className="coupang-source-row"><label className="check"><input type="checkbox" checked={value.coupangPlIncluded} onChange={event=>patch('coupangPlIncluded',event.target.checked)}/> 쿠팡 파트너스 PL 포함</label><select aria-label="쿠팡 파트너스 PL" value={value.coupangPlBrandId} disabled={!value.coupangPlIncluded} onChange={event=>patch('coupangPlBrandId',event.target.value as CoupangProductSearchSettings['coupangPlBrandId'])}><option value="ALL">전체</option>{COUPANG_PL_BRAND_OPTIONS.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></div>
    </fieldset>
    <fieldset className="coupang-delivery-options"><legend>배송 조건 · 결과에 적용</legend><label className="check"><input type="checkbox" checked={value.rocketOnly} onChange={event=>patch('rocketOnly',event.target.checked)}/> 로켓배송 상품만</label><label className="check"><input type="checkbox" checked={value.rocketFreshOnly} onChange={event=>patch('rocketFreshOnly',event.target.checked)}/> 로켓프레시 중심</label></fieldset>
  </div>;
}

function CoupangQueueCard({item,busy,selectable,selected,selectionFull,onSelect,onPrepare,onRetry,onDelete,onSaveDraft,onRemoveImage}:{item:CoupangQueueItem;busy:boolean;selectable:boolean;selected:boolean;selectionFull:boolean;onSelect:(item:CoupangQueueItem,selected:boolean)=>void;onPrepare:(item:CoupangQueueItem)=>void;onRetry:(item:CoupangQueueItem)=>void;onDelete:(item:CoupangQueueItem)=>void;onSaveDraft:(item:CoupangQueueItem,body:string)=>Promise<void>;onRemoveImage:(item:CoupangQueueItem,imageUrl:string)=>Promise<void>}) {
  const providerName=item.providerType==='NAVER_BRAND_CONNECT'?'네이버':'쿠팡 파트너스';
  const informationRequired=item.metadataStatus==='INFORMATION_REQUIRED';
  const facts=coupangFactsText(item.productFacts);
  const canPrepare=item.status==='QUEUED'||item.status==='INFORMATION_REQUIRED';
  const canRetry=!informationRequired&&['FAILED','REVIEW_REQUIRED','PREVIEW_READY'].includes(item.status);
  const gallery=(item.imageUrls?.length?item.imageUrls:item.imageUrl?[item.imageUrl]:[]).slice(0,20);
  const detailsRef=React.useRef<HTMLDetailsElement>(null);
  const imageDialogRef=React.useRef<HTMLElement>(null);
  const [selectedImage,setSelectedImage]=useState<{url:string;index:number}>();
  useDialogKeyboard(imageDialogRef,()=>setSelectedImage(undefined),Boolean(selectedImage));
  const [body,setBody]=useState(item.draftBody??'');const [editError,setEditError]=useState('');
  const [draftDirty,setDraftDirty]=useState(false);
  const editable=item.status==='PREVIEW_READY'&&Boolean(item.draftPostId);
  const completeDraft=editable&&Boolean(item.draftBody?.trim());
  const save=async()=>{setEditError('');try{await onSaveDraft(item,body);setDraftDirty(false);}catch(error){setEditError(cleanError(error));}};
  const scrollToOpenedItem=()=>{const details=detailsRef.current;if(!details?.open)return;window.requestAnimationFrame(()=>details.querySelector('summary')?.scrollIntoView({behavior:'smooth',block:'start'}));};
  return <details ref={detailsRef} onToggle={scrollToOpenedItem} className={`coupang-queue-item ${informationRequired?'information-required':''}`}>
    <summary className="coupang-product-head">
      {selectable?<input className="coupang-queue-checkbox" type="checkbox" aria-label={`${item.productName||'상품'} 일괄 분석 선택`} checked={selected} disabled={busy||(!selected&&selectionFull)} onClick={event=>event.stopPropagation()} onChange={event=>onSelect(item,event.target.checked)}/>:<span className="coupang-queue-checkbox-spacer" aria-hidden="true"/>}
      <div className="coupang-product-image">{gallery[0]?<img src={gallery[0]} alt={item.productName?`${item.productName} 대표 이미지`:`${providerName} 상품 대표 이미지`} referrerPolicy="no-referrer"/>:<span>{item.status==='PROCESSING'?'이미지\n조사 중':informationRequired?'재분석\n필요':'이미지 없음'}</span>}</div>
      <div className="coupang-product-copy"><div className="coupang-product-title"><strong>{item.productName||'상품 정보 확인 필요'}</strong><span className={`live-status ${coupangQueueTone(item)}`}>{coupangQueueStatusLabel(item.status)}</span></div><small className="coupang-product-url" title={item.affiliateUrl}>{item.affiliateUrl}</small><div className="coupang-research-state"><small>{item.researchVerified?`이미지 ${gallery.length}장 · 후기 근거 ${item.reviewCount??item.reviewEvidence?.length??0}건`:'페이지 조사 전'}</small></div></div>
      <span className="coupang-expand-label">상세 <i aria-hidden="true">⌄</i></span>
    </summary>
    <div className="coupang-queue-detail">
      {facts&&<p className="coupang-facts">{facts}</p>}{informationRequired&&<p className="coupang-information-required">‘다시 분석’을 눌러 상품 페이지를 다시 확인하세요. 접근 제한이 계속되면 잠시 뒤 직접 재시도하세요.</p>}{item.lastError&&!informationRequired&&<p className="coupang-item-error">{item.lastError}</p>}
      {gallery.length>0&&<div className="coupang-gallery" aria-label={`발행 예정 상품 이미지 ${gallery.length}장`}><div className="coupang-gallery-label"><strong>발행 이미지</strong><span>이미지를 클릭하면 600×600으로 크게 확인됩니다 · {gallery.length}/20</span></div><div className="coupang-gallery-strip">{gallery.map((url,index)=><div className="coupang-gallery-thumb" key={`${url}-${index}`}><button type="button" className="coupang-image-preview-trigger" aria-label={`발행 예정 이미지 ${index+1} 크게 보기`} onClick={()=>setSelectedImage({url,index})}><img src={url} alt={`발행 예정 상품 이미지 ${index+1}`} loading="lazy" referrerPolicy="no-referrer"/></button><button type="button" className="coupang-image-delete" aria-label={`발행 예정 이미지 ${index+1} 삭제`} title="이 이미지 삭제" disabled={busy||!editable||gallery.length<=1} onClick={()=>void onRemoveImage(item,url)}>×</button></div>)}</div></div>}
      {selectedImage&&<div className="modal-backdrop coupang-image-modal-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)setSelectedImage(undefined);}}><section ref={imageDialogRef} className="coupang-image-modal" role="dialog" aria-modal="true" aria-labelledby="coupang-image-modal-title"><header><div><h2 id="coupang-image-modal-title">발행 이미지 {selectedImage.index+1}</h2><p>실제 발행에 사용할 이미지를 600×600 영역에서 확인합니다.</p></div><button type="button" className="icon-button" aria-label="이미지 크게 보기 닫기" onClick={()=>setSelectedImage(undefined)}>×</button></header><div className="coupang-image-modal-body"><img src={selectedImage.url} alt={`발행 예정 상품 이미지 ${selectedImage.index+1} 확대`} referrerPolicy="no-referrer"/></div></section></div>}
      {item.status==='PREVIEW_READY'&&!completeDraft&&<div className="alert" role="alert">발행 준비본 연결 정보가 완전하지 않습니다. ‘다시 준비’를 눌러 최종 발행 본문을 다시 생성하세요.</div>}
      <div className="coupang-generated-copy" aria-label="생성된 발행 내용">
        <section><header><strong>최종 발행 단일 본문</strong><span>{body.trim()?`${body.trim().length}자`:'미생성'}</span></header><textarea value={body} rows={10} disabled={!editable||busy} placeholder="※ 고지문 ※, 광고 문장, 빈 줄, 상품 링크가 포함된 최종 본문이 표시됩니다. 이미지는 링크 다음에 첨부됩니다." onChange={event=>{setBody(event.target.value);setDraftDirty(true);}}/></section>
      </div>
      {editError&&<div className="alert" role="alert">{editError}</div>}
      <div className="coupang-item-actions"><button type="button" className="primary" disabled={busy||!editable||!draftDirty||!body.trim()} onClick={()=>void save()}>최종 본문 변경 저장</button>{canPrepare&&<button type="button" disabled={busy} onClick={()=>onPrepare(item)}>{informationRequired?'다시 분석':'분석 및 생성'}</button>}{canRetry&&<button type="button" disabled={busy} onClick={()=>onRetry(item)}>{item.researchVerified?'재분석':'다시 준비'}</button>}<button type="button" className="danger-link" disabled={busy||item.status==='PROCESSING'} onClick={()=>onDelete(item)}>상품 자료 삭제</button></div>
    </div>
  </details>;
}

function AccountSettingsCard({account,onSaved,defaultOpen}:{account:Account;onSaved:()=>Promise<void>;defaultOpen:boolean}) {
  const [daily,setDaily]=useState(account.dailyEnabled);const [blog,setBlog]=useState(false);const [youtube,setYoutube]=useState(false);const [coupang,setCoupang]=useState(false);const [naverBrand,setNaverBrand]=useState(false);
  const [expanded,setExpanded]=useState(defaultOpen);
  const [connectionToast,setConnectionToast]=useState<{service:string;ok:boolean}>();
  useEffect(()=>{if(!connectionToast)return;const timer=window.setTimeout(()=>setConnectionToast(undefined),2000);return()=>window.clearTimeout(timer);},[connectionToast]);
  const [blogUrl,setBlogUrl]=useState('');const [youtubeChannel,setYoutubeChannel]=useState('');const [youtubeLongForm,setYoutubeLongForm]=useState(true);const [youtubeShorts,setYoutubeShorts]=useState(true);const [secrets,setSecrets]=useState<Record<string,string>>({});const [status,setStatus]=useState<CredentialState>({});const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [hydrated,setHydrated]=useState(false);
  const [coupangMode,setCoupangMode]=useState<CoupangMode>('MANUAL_LINKS');const [coupangConfig,setCoupangConfig]=useState<Record<string,unknown>>({mode:'MANUAL_LINKS'});
  const [tokenStatus,setTokenStatus]=useState<ThreadsTokenStatus>({accountId:account.id,stored:false,valid:account.threadsTokenValid,issuedAt:account.threadsTokenIssuedAt,expiresAt:account.threadsTokenExpiresAt,dataAccessExpiresAt:account.threadsTokenDataAccessExpiresAt,checkedAt:account.threadsTokenCheckedAt,scopes:account.threadsTokenScopes??[],missingScopes:[],fresh:false,estimated:!account.threadsTokenCheckedAt,lastRefreshedAt:account.threadsTokenLastRefreshedAt,canRefresh:false,state:'UNKNOWN',message:'토큰 상태를 확인하고 있습니다.'});const [refreshingToken,setRefreshingToken]=useState(false);const [tokenRefreshMessage,setTokenRefreshMessage]=useState('');
  const [integrationOpen,setIntegrationOpen]=useState(false);const [integrationBusy,setIntegrationBusy]=useState(false);const [integrationRun,setIntegrationRun]=useState<ThreadsIntegrationRun>();const [integrationError,setIntegrationError]=useState('');
  const integrationDialogRef=React.useRef<HTMLElement>(null);useDialogKeyboard(integrationDialogRef,()=>{if(!integrationBusy)setIntegrationOpen(false);},integrationOpen);
  const keys=[scopedKey('threadsToken',account.id),scopedKey('youtubeApiKey',account.id),scopedKey('coupangAccessKey',account.id),scopedKey('coupangSecretKey',account.id)];
  const load=async()=>{const [providers,credentialStatus,threadsTokenStatus]=await Promise.all([window.threadsAuto.providers.list(account.id),window.threadsAuto.credentials.status(keys),window.threadsAuto.accounts.tokenStatus(account.id)]);const y=providers.find((item:any)=>item.type==='YOUTUBE');const b=providers.find((item:any)=>item.type==='BLOG');const c=providers.find((item:any)=>item.type==='COUPANG');const n=providers.find((item:any)=>item.type==='NAVER_BRAND_CONNECT');const cConfig=Object(c?.config??{}) as Record<string,unknown>;const storedMode=cConfig.mode==='OPEN_API'||cConfig.mode==='MANUAL_LINKS'?cConfig.mode:credentialStatus[scopedKey('coupangAccessKey',account.id)]?.stored&&credentialStatus[scopedKey('coupangSecretKey',account.id)]?.stored?'OPEN_API':'MANUAL_LINKS';setYoutube(Boolean(y?.enabled));setYoutubeChannel(String(y?.config?.channel??''));setYoutubeLongForm(y?.config?.includeLongForm!==false);setYoutubeShorts(y?.config?.includeShorts!==false);setBlog(Boolean(b?.enabled));setBlogUrl(String(b?.config?.rssUrl??''));setCoupang(Boolean(c?.enabled));setNaverBrand(Boolean(n?.enabled));setCoupangMode(storedMode);setCoupangConfig({schemaVersion:1,...cConfig,...normalizeCoupangProductSearchSettings(cConfig),mode:storedMode});setStatus(credentialStatus);setTokenStatus(threadsTokenStatus);setHydrated(true);};
  useEffect(()=>{let active=true;const initialKeys=[scopedKey('threadsToken',account.id),scopedKey('youtubeApiKey',account.id),scopedKey('coupangAccessKey',account.id),scopedKey('coupangSecretKey',account.id)];void Promise.all([window.threadsAuto.providers.list(account.id),window.threadsAuto.credentials.status(initialKeys),window.threadsAuto.accounts.tokenStatus(account.id)]).then(([providers,credentialStatus,threadsTokenStatus])=>{if(!active)return;const y=providers.find((item:any)=>item.type==='YOUTUBE');const b=providers.find((item:any)=>item.type==='BLOG');const c=providers.find((item:any)=>item.type==='COUPANG');const n=providers.find((item:any)=>item.type==='NAVER_BRAND_CONNECT');const cConfig=Object(c?.config??{}) as Record<string,unknown>;const storedMode=cConfig.mode==='OPEN_API'||cConfig.mode==='MANUAL_LINKS'?cConfig.mode:credentialStatus[scopedKey('coupangAccessKey',account.id)]?.stored&&credentialStatus[scopedKey('coupangSecretKey',account.id)]?.stored?'OPEN_API':'MANUAL_LINKS';setYoutube(Boolean(y?.enabled));setYoutubeChannel(String(y?.config?.channel??''));setYoutubeLongForm(y?.config?.includeLongForm!==false);setYoutubeShorts(y?.config?.includeShorts!==false);setBlog(Boolean(b?.enabled));setBlogUrl(String(b?.config?.rssUrl??''));setCoupang(Boolean(c?.enabled));setNaverBrand(Boolean(n?.enabled));setCoupangMode(storedMode);setCoupangConfig({schemaVersion:1,...cConfig,...normalizeCoupangProductSearchSettings(cConfig),mode:storedMode});setStatus(credentialStatus);setTokenStatus(threadsTokenStatus);setHydrated(true);}).catch(e=>{if(active)setMessage(cleanError(e));});return()=>{active=false;};},[account.id]);
  useEffect(()=>{let active=true;void window.threadsAuto.accounts.tokenStatus(account.id).then(value=>{if(active)setTokenStatus(value);}).catch(()=>{if(active)setTokenStatus(current=>({...current,state:'CHECK_FAILED',valid:undefined,fresh:false,canRefresh:false}));});return()=>{active=false;};},[account.id,account.updatedAt]);
  useEffect(()=>{let active=true;void window.threadsAuto.threadsIntegration.list(account.id,20).then(async runs=>{if(!active||!runs[0])return;const selected=runs.find(run=>run.status==='CLEANUP_REQUIRED'||run.status==='RUNNING')??runs[0];const run=await window.threadsAuto.threadsIntegration.get(selected.id);if(active&&run)setIntegrationRun(run);}).catch(()=>undefined);return()=>{active=false;};},[account.id]);
  useEffect(()=>{if(!integrationBusy)return;const poll=()=>window.threadsAuto.threadsIntegration.list(account.id,1).then(runs=>{if(runs[0])return window.threadsAuto.threadsIntegration.get(runs[0].id).then(run=>{if(run)setIntegrationRun(run);});}).catch(()=>undefined);void poll();const timer=window.setInterval(()=>void poll(),700);return()=>window.clearInterval(timer);},[account.id,integrationBusy]);
  const setSecret=(key:CredentialKey,value:string)=>setSecrets(current=>({...current,[key]:value}));
  const tokenKey=scopedKey('threadsToken',account.id),youtubeKey=scopedKey('youtubeApiKey',account.id),coupangAccess=scopedKey('coupangAccessKey',account.id),coupangSecret=scopedKey('coupangSecretKey',account.id);
  const hasCoupangKeys=Boolean((status[coupangAccess]?.stored||secrets[coupangAccess]?.trim())&&(status[coupangSecret]?.stored||secrets[coupangSecret]?.trim()));
  const persist=async()=>{if(!hydrated)throw new Error('계정 연결 정보를 불러온 뒤 다시 저장하세요.');if(!daily&&!blog&&!youtube&&!coupang&&!naverBrand)throw new Error('일상·블로그·유튜브·쿠팡 파트너스·네이버 브랜드 커넥트 중 하나 이상을 선택하세요.');if(youtube&&!youtubeLongForm&&!youtubeShorts)throw new Error('유튜브는 롱폼 또는 쇼츠 중 하나 이상을 선택하세요.');if(coupang&&coupangMode==='OPEN_API'&&!String(coupangConfig.keyLabel??'').trim())throw new Error('쿠팡 파트너스 키 구분명을 입력하세요.');const tokenValue=secrets[tokenKey]?.trim();const profileAccount=tokenValue?await window.threadsAuto.accounts.updateToken(account.id,tokenValue):account;for(const [key,value] of Object.entries(secrets))if(key!==tokenKey&&value.trim())await window.threadsAuto.credentials.save(key as CredentialKey,value.trim());await window.threadsAuto.providers.save({accountId:account.id,type:'BLOG',enabled:blog,config:{rssUrl:blogUrl.trim()}});await window.threadsAuto.providers.save({accountId:account.id,type:'YOUTUBE',enabled:youtube,config:{channel:youtubeChannel.trim(),includeLongForm:youtubeLongForm,includeShorts:youtubeShorts}});await window.threadsAuto.providers.save({accountId:account.id,type:'COUPANG',enabled:coupang,config:{...coupangConfig,keyLabel:String(coupangConfig.keyLabel??'').trim(),mode:coupangMode}});await window.threadsAuto.providers.save({accountId:account.id,type:'NAVER_BRAND_CONNECT',enabled:naverBrand,config:{schemaVersion:1}});await window.threadsAuto.accounts.save({...profileAccount,dailyEnabled:daily,promotionEnabled:blog||youtube||coupang||naverBrand});setSecrets({});await load();await onSaved();};
  const save=async()=>{setBusy(true);setMessage('');try{await persist();setMessage('계정 성격과 연동 설정을 저장했습니다.');}catch(e){setMessage(cleanError(e));}finally{setBusy(false);}};
  const removeSecret=async(key:CredentialKey)=>{if(!window.confirm('저장된 키를 삭제하시겠습니까?'))return;setBusy(true);setMessage('');try{await window.threadsAuto.credentials.delete(key);await load();await onSaved();setMessage(key.startsWith('threadsToken:')?'Threads 토큰을 삭제하고 발행 자동화를 해제했습니다.':'저장된 키를 삭제했습니다.');}catch(e){setMessage(cleanError(e));}finally{setBusy(false);}};
  const clearProvider=async(type:'BLOG'|'YOUTUBE'|'COUPANG'|'NAVER_BRAND_CONNECT')=>{setBusy(true);setMessage('');try{const remaining=[blog&&type!=='BLOG',youtube&&type!=='YOUTUBE',coupang&&type!=='COUPANG',naverBrand&&type!=='NAVER_BRAND_CONNECT'].some(Boolean);if(!daily&&!remaining)throw new Error('계정 성격은 하나 이상 필요합니다. 먼저 다른 성격을 선택해 저장하세요.');await window.threadsAuto.providers.delete(account.id,type);if(type==='BLOG'){setBlog(false);setBlogUrl('');}if(type==='YOUTUBE'){setYoutube(false);setYoutubeChannel('');setYoutubeLongForm(true);setYoutubeShorts(true);}if(type==='COUPANG')setCoupang(false);if(type==='NAVER_BRAND_CONNECT')setNaverBrand(false);await window.threadsAuto.accounts.save({...account,dailyEnabled:daily,promotionEnabled:remaining});await onSaved();setMessage(`${sourceLabel(type)} 설정을 삭제했습니다.`);}catch(e){setMessage(cleanError(e));}finally{setBusy(false);}};
  const reloadTokenStatus=async()=>{try{setTokenStatus(await window.threadsAuto.accounts.tokenStatus(account.id));}catch{setTokenStatus(current=>({...current,valid:undefined,state:'CHECK_FAILED',fresh:false,canRefresh:false,message:'토큰 상태를 불러오지 못했습니다. 다시 확인하세요.'}));}};
  const checkThreads=async()=>{setBusy(true);setConnectionToast(undefined);setMessage('Threads 계정을 확인하고 있습니다…');try{const entered=secrets[tokenKey]?.trim();const verified=entered?await window.threadsAuto.accounts.updateToken(account.id,entered):await window.threadsAuto.accounts.verify(account.id);setSecrets(current=>({...current,[tokenKey]:''}));await onSaved();await load();setMessage(`연결 확인 완료 · ${verified.name} · @${verified.threadsHandle}`);setConnectionToast({service:'Threads',ok:true});}catch(e){await reloadTokenStatus();await onSaved();setMessage(cleanError(e));setConnectionToast({service:'Threads',ok:false});}finally{setBusy(false);}};
  const refreshThreadsToken=async()=>{setRefreshingToken(true);setTokenRefreshMessage('Threads 토큰을 연장하고 있습니다…');try{const refreshed=await window.threadsAuto.accounts.refreshToken(account.id);setTokenStatus(refreshed);await load();await onSaved();setTokenRefreshMessage(`연장 완료 · 새 만료일 ${refreshed.expiresAt?fmtDate(refreshed.expiresAt):'확인 필요'}`);}catch(e){await reloadTokenStatus();await onSaved();setTokenRefreshMessage(`연장 실패 · ${cleanError(e)}`);}finally{setRefreshingToken(false);}};
  const startIntegration=async()=>{if(!window.confirm('실제 Threads API 통합 테스트를 실행합니다.\n\nAgent가 일상 본문을 생성해 실제 발행하고, 프로그램 계정으로 댓글과 대댓글을 작성한 뒤 대댓글 → 댓글 → 본문 순서로 삭제합니다. 자동화가 일시정지된 상태에서 계속하시겠습니까?'))return;setIntegrationOpen(true);setIntegrationBusy(true);setIntegrationRun(undefined);setIntegrationError('');try{const run=await window.threadsAuto.threadsIntegration.start(account.id);setIntegrationRun(await window.threadsAuto.threadsIntegration.get(run.id)??run);await onSaved();}catch(e){const text=cleanError(e);setIntegrationError(text);setMessage(text);}finally{setIntegrationBusy(false);}};
  const recoverIntegration=async()=>{if(!integrationRun||!window.confirm('저장된 ID와 소유 관계를 다시 확인한 뒤, 남은 테스트 항목을 대댓글 → 댓글 → 본문 순서로 API 삭제합니다. 계속하시겠습니까?'))return;setIntegrationBusy(true);setIntegrationError('');try{setIntegrationRun(await window.threadsAuto.threadsIntegration.recover(integrationRun.id));await onSaved();}catch(e){setIntegrationError(cleanError(e));}finally{setIntegrationBusy(false);}};
  const test=async(type:'YOUTUBE'|'BLOG'|'COUPANG')=>{setBusy(true);setConnectionToast(undefined);setMessage('연결을 확인하고 있습니다…');try{await persist();const config=type==='YOUTUBE'?{channel:youtubeChannel,includeLongForm:youtubeLongForm,includeShorts:youtubeShorts}:type==='BLOG'?{rssUrl:blogUrl}:{};const result=await window.threadsAuto.connections.test(type,account.id,config);setMessage(result.message);setConnectionToast({service:sourceLabel(type),ok:result.ok});}catch(e){setMessage(cleanError(e));setConnectionToast({service:sourceLabel(type),ok:false});}finally{setBusy(false);}};
  const selectCoupang=(enabled:boolean)=>setCoupang(enabled);
  return <><details className="account-settings-card" open={expanded} onToggle={event=>setExpanded(event.currentTarget.open)}><summary><div><strong>{account.name}</strong><small>{hydrated?threadsAuthLabel(tokenStatus):'Threads 상태 확인 중'}</small></div><div className="source-chips">{[daily&&'DAILY',blog&&'BLOG',youtube&&'YOUTUBE',coupang&&'COUPANG',naverBrand&&'NAVER_BRAND_CONNECT'].filter(Boolean).map(type=><span className="badge" key={String(type)}>{sourceLabel(String(type))}</span>)}</div></summary><div className="account-settings-body">
    {connectionToast&&<div className={`connection-toast ${connectionToast.ok?'success':'error'}`} role={connectionToast.ok?'status':'alert'} aria-atomic="true"><span aria-hidden="true">{connectionToast.ok?'✓':'!'}</span><div><strong>{connectionToast.service} {connectionToast.ok?'연결 확인 완료':'연결 확인 실패'}</strong><small>{account.name}{!connectionToast.ok?' · 상세 내용은 계정 카드 상단에서 확인하세요.':''}</small></div></div>}
    {message&&<div className="notice" aria-live="polite">{message}</div>}
    <section className="integration-block provider-neutral"><header><ProviderHeading icon="◆" title="콘텐츠 성격" description="운영할 자료 성격을 선택합니다. 계정 말투와 운영시간은 위 운영정보에서 관리합니다."/></header><div className="type-selector"><label><input type="checkbox" checked={daily} onChange={e=>setDaily(e.target.checked)}/><span>일상</span></label><label><input type="checkbox" checked={blog} onChange={e=>setBlog(e.target.checked)}/><span>블로그</span></label><label><input type="checkbox" checked={youtube} onChange={e=>setYoutube(e.target.checked)}/><span>유튜브</span></label><label><input type="checkbox" checked={coupang} onChange={e=>selectCoupang(e.target.checked)}/><span>쿠팡 파트너스</span></label><label><input type="checkbox" checked={naverBrand} onChange={e=>setNaverBrand(e.target.checked)}/><span>네이버 브랜드 커넥트</span></label></div></section>
    <section className="integration-block provider-threads"><header><ProviderHeading icon="T" title="Threads 발행" description="장기 Access Token을 검증하면 계정 정보가 자동으로 저장됩니다."/><div className="actions"><button disabled={busy||refreshingToken||(!status[tokenKey]?.stored&&!secrets[tokenKey]?.trim())} onClick={()=>void checkThreads()}>연결 확인</button>{integrationRun&&<button onClick={()=>setIntegrationOpen(true)}>최근 테스트 결과</button>}<button className="integration-test-button" disabled={busy||refreshingToken||integrationBusy||!account.threadsUserId||!status[tokenKey]?.stored||(integrationRun?.status==='CLEANUP_REQUIRED'||integrationRun?.status==='RUNNING')} onClick={()=>void startIntegration()}>{integrationBusy?'실제 테스트 중…':'실제 API 통합 테스트'}</button></div></header>{account.threadsUserId?<dl className="threads-identity"><div><dt>표시명</dt><dd>{account.name}</dd></div><div><dt>사용자명</dt><dd>@{account.threadsHandle.replace(/^@/,'')}</dd></div><div><dt>Threads ID</dt><dd className="mono">{account.threadsUserId}</dd></div></dl>:<div className="inline-warning">연결 확인을 누르면 표시명, 사용자명과 Threads ID가 자동으로 표시됩니다.</div>}<div className="credential-grid single"><SecretControl label="Threads Access Token" credentialKey={tokenKey} value={secrets[tokenKey]??''} status={status[tokenKey]} onChange={value=>setSecret(tokenKey,value)} onDelete={()=>void removeSecret(tokenKey)}/></div><ThreadsTokenExpiry accountId={account.id} status={tokenStatus} busy={refreshingToken} message={tokenRefreshMessage} onRefresh={()=>void refreshThreadsToken()}/><p className="integration-test-note">실제 테스트는 Agent 일상 본문 → 발행 → 댓글 → 대댓글 → 역순 삭제를 프로그램 내부 API로 검증하고 결과를 영구 기록합니다. 삭제 확인이 남아 있으면 새 테스트 대신 최근 결과에서 정리를 다시 실행합니다.</p></section>
    {blog&&<section className="integration-block provider-blog"><header><ProviderHeading icon="B" title="블로그 자료" description="네이버 블로그 주소 또는 RSS/Atom 주소를 입력할 수 있습니다."/><div className="actions"><button disabled={busy||!blogUrl} onClick={()=>void test('BLOG')}>연결 확인</button><button className="danger-link" onClick={()=>void clearProvider('BLOG')}>설정 삭제</button></div></header><Field label="블로그 주소 / RSS"><input type="url" value={blogUrl} placeholder="https://blog.naver.com/..." onChange={e=>setBlogUrl(e.target.value)}/></Field></section>}
    {youtube&&<section className="integration-block provider-youtube"><header><ProviderHeading icon="▶" title="유튜브 자료" description="채널과 API 키, 발행할 영상 형식은 이 계정에만 적용됩니다."/><div className="actions"><button disabled={busy||!hydrated||!youtubeChannel||(!youtubeLongForm&&!youtubeShorts)||!(status[youtubeKey]?.stored||secrets[youtubeKey]?.trim())} onClick={()=>void test('YOUTUBE')}>연결 확인</button><button className="danger-link" onClick={()=>void clearProvider('YOUTUBE')}>설정 삭제</button></div></header><div className="credential-grid"><Field label="YouTube 채널 URL / ID / @handle"><input value={youtubeChannel} placeholder="https://youtube.com/@channel" onChange={e=>setYoutubeChannel(e.target.value)}/></Field><SecretControl label="YouTube Data API Key" credentialKey={youtubeKey} value={secrets[youtubeKey]??''} status={status[youtubeKey]} onChange={value=>setSecret(youtubeKey,value)} onDelete={()=>void removeSecret(youtubeKey)}/><fieldset className="wide youtube-format-options"><legend>발행할 영상 형식</legend><label className="check"><input type="checkbox" checked={youtubeLongForm} onChange={e=>setYoutubeLongForm(e.target.checked)}/> 롱폼</label><label className="check"><input type="checkbox" checked={youtubeShorts} onChange={e=>setYoutubeShorts(e.target.checked)}/> 쇼츠 (3분 이하)</label><p>영상 길이가 3분 이하이면 쇼츠로 분류합니다. 둘 중 하나 이상을 선택하세요.</p></fieldset></div></section>}
    {coupang&&<section className="integration-block provider-coupang"><header><ProviderHeading icon="C" title="쿠팡 파트너스" description="사용 여부, 승인 상태, 계정별 API 키와 상품 검색 조건만 관리합니다."/><button className="danger-link" onClick={()=>void clearProvider('COUPANG')}>설정 삭제</button></header>
      <div className="coupang-mode-selector" role="group" aria-label="쿠팡 파트너스 운영 방식"><button type="button" className={coupangMode==='MANUAL_LINKS'?'active':''} aria-pressed={coupangMode==='MANUAL_LINKS'} onClick={()=>setCoupangMode('MANUAL_LINKS')}><strong>최종 승인 전</strong><small>상품 자료 직접 등록</small></button><button type="button" className={coupangMode==='OPEN_API'?'active':''} aria-pressed={coupangMode==='OPEN_API'} onClick={()=>setCoupangMode('OPEN_API')}><strong>최종 승인 완료</strong><small>Open API 자동 처리</small></button></div>
      <div className="coupang-disclosure"><span>최종 본문 첫 줄 고정 고지</span><strong>※ 이 게시물은 쿠팡 파트너스 활동의 일환으로, 이에 따른 일정액의 수수료를 제공받습니다. ※</strong><small>Core가 고지문, 빈 줄, Agent가 검수한 광고 문장, 빈 줄, 상품 링크를 하나의 본문으로 만듭니다.</small></div>
      {coupangMode==='MANUAL_LINKS'?<div className="coupang-api-status"><strong>직접 등록 방식</strong><p>상품 링크 등록, 이미지·후기 분석, 본문 생성과 발행 전 목록 관리는 왼쪽의 ‘쿠팡 파트너스’ 메뉴에서 처리합니다.</p></div>:<div className="coupang-api-panel"><div className="coupang-api-status"><strong>Open API 상품 선택 방식</strong><p>이 계정의 키로 상품을 검색하고 사용자가 고른 상품만 준비합니다. 예약 시점에 앱이 임의로 상품을 선택하지 않습니다.</p></div><div className="credential-grid"><Field label="쿠팡 파트너스 키 구분명" wide><input maxLength={100} value={String(coupangConfig.keyLabel??'')} placeholder="예: 복사장 파트너스" onChange={e=>setCoupangConfig(current=>({...current,keyLabel:e.target.value}))}/><small>같은 Access Key와 Secret Key를 사용하는 Threads 계정에는 같은 구분명을 입력하세요.</small></Field><SecretControl label="Coupang Access Key" credentialKey={coupangAccess} value={secrets[coupangAccess]??''} status={status[coupangAccess]} onChange={value=>setSecret(coupangAccess,value)} onDelete={()=>void removeSecret(coupangAccess)}/><SecretControl label="Coupang Secret Key" credentialKey={coupangSecret} value={secrets[coupangSecret]??''} status={status[coupangSecret]} onChange={value=>setSecret(coupangSecret,value)} onDelete={()=>void removeSecret(coupangSecret)}/></div><CoupangSearchOptions value={normalizeCoupangProductSearchSettings(coupangConfig)} onChange={next=>setCoupangConfig(current=>({...current,...next}))}/><div className="settings-actions"><button type="button" disabled={busy||!hasCoupangKeys||!String(coupangConfig.keyLabel??'').trim()} onClick={()=>void test('COUPANG')}>Open API 연결 확인</button></div></div>}
      <p className="coupang-save-note">운영 방식 변경은 아래의 ‘이 계정 설정 저장’을 누른 뒤 적용됩니다.</p>
    </section>}
    {naverBrand&&<section className="integration-block provider-naver"><header><ProviderHeading icon="N" title="네이버 브랜드 커넥트" description="API 없이 사용자가 등록한 제휴 링크의 상품 페이지를 Chrome에서 분석합니다."/><button className="danger-link" onClick={()=>void clearProvider('NAVER_BRAND_CONNECT')}>설정 삭제</button></header><div className="coupang-disclosure"><span>최종 본문 첫 줄 고정 고지</span><strong>※ 이 포스팅은 네이버 쇼핑 커넥트 활동의 일환으로, 판매 발생 시 수수료를 제공받습니다. ※</strong><small>상품 링크 등록, 이미지·후기 분석, 본문 생성과 발행 전 목록 관리는 왼쪽의 ‘네이버 브랜드 커넥트’ 메뉴에서 처리합니다.</small></div></section>}
    <div className="settings-actions"><button className="primary" disabled={busy||!hydrated} onClick={()=>void save()}>{!hydrated?'연결 정보 불러오는 중…':busy?'처리 중…':'이 계정 설정 저장'}</button></div>
  </div></details>{integrationOpen&&<div className="modal-backdrop" role="presentation"><section ref={integrationDialogRef} className="modal integration-test-modal" role="dialog" aria-modal="true" aria-labelledby="integration-title"><header><div><h2 id="integration-title">Threads 실제 API 통합 테스트</h2><p>{account.name} · 브라우저 조작 없이 프로그램 API만 사용</p></div><button className="icon-button" disabled={integrationBusy} aria-label="닫기" onClick={()=>setIntegrationOpen(false)}>×</button></header><div className="modal-body stack"><div className={`integration-result ${integrationRun?.status==='PASS'?'success':integrationRun?.status==='FAILED'||integrationRun?.status==='CLEANUP_REQUIRED'||integrationError?'danger':'working'}`}><span>{integrationRun?.status==='PASS'?'✓':integrationRun?.status==='FAILED'||integrationRun?.status==='CLEANUP_REQUIRED'||integrationError?'!':'●'}</span><div><strong>{integrationRun?.status==='PASS'?'전체 과정 통과':integrationRun?.status==='CLEANUP_REQUIRED'?'삭제 확인 필요':integrationRun?.status==='FAILED'||integrationError?'테스트 실패':'테스트 진행 중'}</strong><p>{integrationRun?.message??integrationError??'Agent 일상 본문 생성을 준비하고 있습니다.'}</p></div></div>{integrationError&&<div className="alert">{integrationError}</div>}{integrationRun?.draftBody&&<article className="draft-preview"><small>실제 발행 본문</small>{integrationRun.draftBody}</article>}<div className="integration-event-list" aria-live="polite">{integrationRun?.events?.length?integrationRun.events.map(event=><div className={`integration-event ${event.level.toLowerCase()}`} key={event.id}><time>{new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(event.createdAt))}</time><span>{event.level==='INFO'?'진행':event.level==='WARN'?'경고':'실패'}</span><p>{event.message}</p></div>):<p className="workspace-placeholder">실행 단계가 시작되면 여기에 순서대로 표시됩니다.</p>}</div>{integrationRun?.errorSummary&&<div className="alert">{integrationRun.errorSummary}</div>}{integrationRun&&<dl className="detail-facts"><div><dt>본문</dt><dd className="mono">{integrationRun.parentId??'-'}</dd></div><div><dt>댓글</dt><dd className="mono">{integrationRun.replyId??'-'}</dd></div><div><dt>대댓글</dt><dd className="mono">{integrationRun.nestedReplyId??'-'}</dd></div></dl>}</div><footer><button disabled={integrationBusy} onClick={()=>setIntegrationOpen(false)}>{integrationBusy?'진행 중…':'닫기'}</button>{(integrationRun?.status==='CLEANUP_REQUIRED'||integrationRun?.status==='RUNNING')&&<button className="danger-button" disabled={integrationBusy} onClick={()=>void recoverIntegration()}>남은 테스트 글 API 정리</button>}</footer></section></div>}</>;
}

type CoupangSearchSettings=CoupangProductSearchSettings;
const defaultCoupangSearchSettings:CoupangSearchSettings=DEFAULT_COUPANG_PRODUCT_SEARCH_SETTINGS;

function CoupangProducts({snapshot,selectedAccountId,onSelectAccount,refresh}:{snapshot:AppSnapshot;selectedAccountId:string;onSelectAccount:(accountId:string)=>void;refresh:()=>Promise<void>}){
  const account=snapshot.accounts.find((item)=>item.id===selectedAccountId)??snapshot.accounts[0];
  const accountId=account?.id;
  const [enabled,setEnabled]=useState(false);const [mode,setMode]=useState<CoupangMode>('MANUAL_LINKS');const [providerConfig,setProviderConfig]=useState<Record<string,unknown>>({schemaVersion:1,mode:'MANUAL_LINKS'});
  const [searchSettings,setSearchSettings]=useState<CoupangSearchSettings>(defaultCoupangSearchSettings);const [items,setItems]=useState<CoupangQueueItem[]>([]);const [input,setInput]=useState('');
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [collectorStatus,setCollectorStatus]=useState<CoupangCollectorStatus>();const [collectorPromptOpen,setCollectorPromptOpen]=useState(false);const collectorPromptHandled=React.useRef(false);
  const [searchOpen,setSearchOpen]=useState(false);const [searchBusy,setSearchBusy]=useState(false);const [searchResults,setSearchResults]=useState<SourceCandidate[]>([]);const [searchMessage,setSearchMessage]=useState('');const [selectedCandidates,setSelectedCandidates]=useState<Set<string>>(()=>new Set());
  const [selectedQueueItems,setSelectedQueueItems]=useState<Set<string>>(()=>new Set());
  const searchDialogRef=React.useRef<HTMLElement>(null);useDialogKeyboard(searchDialogRef,()=>{if(!searchBusy)setSearchOpen(false);},searchOpen);
  useEffect(()=>window.threadsAuto.coupangCollector.onStatus(setCollectorStatus),[]);
  useEffect(()=>{if(!accountId)return;let active=true;void Promise.all([window.threadsAuto.providers.list(accountId),coupangQueueApi().list(accountId),window.threadsAuto.coupangCollector.status()]).then(([providers,queue,collector])=>{if(!active)return;const coupang=providers.find((item:any)=>item.type==='COUPANG');const config=Object(coupang?.config??{}) as Record<string,unknown>;const currentMode=config.mode==='OPEN_API'?'OPEN_API':'MANUAL_LINKS';setEnabled(Boolean(coupang?.enabled));setMode(currentMode);setProviderConfig({schemaVersion:1,...config,mode:currentMode});setSearchSettings(normalizeCoupangProductSearchSettings(config));setItems(normalizeCoupangQueue(queue));setCollectorStatus(collector);setError('');setNotice('');setSearchResults([]);setSearchMessage('');setSelectedCandidates(new Set());setSelectedQueueItems(new Set());}).catch(value=>{if(active)setError(cleanError(value));});return()=>{active=false;};},[accountId]);
  const visibleItems=useMemo(()=>items.filter((item)=>item.status!=='COMPLETED'),[items]);
  const bulkCandidates=useMemo(()=>visibleItems.filter((item)=>item.status==='QUEUED'||item.status==='INFORMATION_REQUIRED'),[visibleItems]);
  const queueCounts=useMemo(()=>visibleItems.reduce((counts,item)=>{if(item.metadataStatus==='INFORMATION_REQUIRED')counts.attention+=1;else if(item.status==='PROCESSING')counts.processing+=1;else if(item.status==='PREVIEW_READY')counts.draft+=1;else if(['FAILED','INFORMATION_REQUIRED','REVIEW_REQUIRED'].includes(item.status))counts.attention+=1;else counts.waiting+=1;return counts;},{waiting:0,processing:0,draft:0,attention:0}),[visibleItems]);
  const reloadQueue=async()=>{if(account){const queue=normalizeCoupangQueue(await coupangQueueApi().list(account.id));setItems(queue);const valid=new Set(queue.filter((item)=>item.status==='QUEUED'||item.status==='INFORMATION_REQUIRED').map((item)=>item.id));setSelectedQueueItems(current=>new Set([...current].filter((id)=>valid.has(id))));}};
  const refreshCollector=async(showPrompt=false)=>{try{let current=await window.threadsAuto.coupangCollector.status();setCollectorStatus(current);if(showPrompt&&!current.connected&&!current.promptAcknowledged&&!collectorPromptHandled.current){collectorPromptHandled.current=true;setCollectorPromptOpen(true);current=await window.threadsAuto.coupangCollector.acknowledgePrompt();setCollectorStatus(current);}return current;}catch(value){setError(cleanError(value));return undefined;}};
  const addManual=async()=>{if(!account||!input.trim())return;if(!collectorStatus?.connected){setError('Chrome 쿠팡 파트너스 수집기를 연결한 뒤 상품 자료를 분석하세요.');await refreshCollector(true);return;}setBusy(true);setError('');setNotice('');try{await coupangQueueApi().add({accountId:account.id,text:input.trim()});setInput('');await reloadQueue();await refresh();setNotice('상품 이미지·후기와 최종 발행 본문을 분석해 저장했습니다.');}catch(value){await reloadQueue().catch(()=>undefined);setError(cleanError(value));}finally{setBusy(false);}};
  const runSearch=async()=>{if(!account||!hasCoupangProductSource(searchSettings)||(searchSettings.keywordSearchIncluded&&!searchSettings.keywords.trim()))return;setSearchBusy(true);setError('');setNotice('');setSearchMessage('');try{const config={...providerConfig,schemaVersion:1,mode:'OPEN_API' as const,...searchSettings};await window.threadsAuto.providers.save({accountId:account.id,type:'COUPANG',enabled:true,config});setProviderConfig(config);const results=await window.threadsAuto.coupangProducts.search({accountId:account.id,...searchSettings});setSearchResults(results);setSelectedCandidates(new Set());if(!results.length)setError('이미 등록·발행한 상품을 제외하면 새 상품이 없습니다. 키워드를 추가하거나 카테고리·골드박스·쿠팡 파트너스 PL 포함 범위를 넓혀 보세요.');else{const sources=[searchSettings.keywordSearchIncluded&&'키워드',searchSettings.goldBoxIncluded&&'골드박스',searchSettings.categoryBestIncluded&&'카테고리 베스트',searchSettings.coupangPlIncluded&&'쿠팡 파트너스 PL'].filter(Boolean).join(' + ');setSearchMessage(`${sources} 결과를 합치고 이 계정에 이미 등록·발행한 상품을 제외해 새 후보 ${results.length}개를 불러왔습니다.`);}await refresh();}catch(value){setError(cleanError(value));}finally{setSearchBusy(false);}};
  const toggleCandidate=(id:string,checked:boolean)=>setSelectedCandidates(current=>{const next=new Set(current);if(checked){next.add(id);}else next.delete(id);return next;});
  const toggleAllCandidates=(checked:boolean)=>setSelectedCandidates(checked?new Set(searchResults.map((item)=>item.id)):new Set());
  const stageSelected=async()=>{if(!account||!selectedCandidates.size)return;setSearchBusy(true);setError('');try{const staged=await window.threadsAuto.coupangProducts.stage({accountId:account.id,candidateIds:[...selectedCandidates]});await reloadQueue();await refresh();setSearchOpen(false);setSearchResults([]);setSelectedCandidates(new Set());setNotice(`선택한 상품 ${staged.length}건을 추가했습니다. 대기 목록에서 여러 상품을 선택해 한꺼번에 분석·생성할 수 있습니다.`);}catch(value){setError(cleanError(value));}finally{setSearchBusy(false);}};
  const deleteItem=async(item:CoupangQueueItem)=>{if(!account||!window.confirm('이 쿠팡 파트너스 상품 자료를 삭제하시겠습니까?'))return;setBusy(true);setError('');try{await coupangQueueApi().delete({accountId:account.id,id:item.id});await reloadQueue();await refresh();}catch(value){setError(cleanError(value));}finally{setBusy(false);}};
  const prepareItem=async(item:CoupangQueueItem)=>{if(!account)return;setBusy(true);setError('');try{await coupangQueueApi().prepare({accountId:account.id,id:item.id});await reloadQueue();await refresh();setNotice('이미지·후기 분석과 최종 본문 생성을 완료했습니다.');}catch(value){setError(cleanError(value));await reloadQueue().catch(()=>undefined);}finally{setBusy(false);}};
  const retryItem=async(item:CoupangQueueItem)=>{if(!account)return;setBusy(true);setError('');try{await coupangQueueApi().retry({accountId:account.id,id:item.id});await reloadQueue();await refresh();setNotice(item.researchVerified?'상품 페이지를 다시 조사하고 최종 본문을 새로 생성했습니다.':'상품 준비를 다시 완료했습니다.');}catch(value){setError(cleanError(value));}finally{setBusy(false);}};
  const toggleQueueItem=(item:CoupangQueueItem,checked:boolean)=>setSelectedQueueItems(current=>{const next=new Set(current);if(checked){if(next.size>=20)return current;next.add(item.id);}else next.delete(item.id);return next;});
  const toggleAllQueueItems=(checked:boolean)=>setSelectedQueueItems(checked?new Set(bulkCandidates.slice(0,20).map((item)=>item.id)):new Set());
  const prepareSelected=async()=>{if(!account||!selectedQueueItems.size)return;setBusy(true);setError('');setNotice('');try{const result=await coupangQueueApi().prepareMany({accountId:account.id,ids:[...selectedQueueItems]});await reloadQueue();await refresh();setSelectedQueueItems(new Set());if(result.failed.length)setError(`${result.prepared.length}건 분석 완료 · ${result.failed.length}건 실패: ${result.failed[0].message}`);else setNotice(`선택한 상품 ${result.prepared.length}건의 이미지·후기 분석과 최종 본문 생성을 완료했습니다.`);}catch(value){setError(cleanError(value));await reloadQueue().catch(()=>undefined);}finally{setBusy(false);}};
  const saveDraft=async(item:CoupangQueueItem,body:string)=>{if(!account)return;setBusy(true);setError('');try{const updated=await coupangQueueApi().updateDraft({accountId:account.id,id:item.id,body,expectedUpdatedAt:item.updatedAt});setItems(current=>current.map(value=>value.id===updated.id?updated:value));setNotice('쿠팡 파트너스 최종 단일 본문을 저장했습니다.');}catch(value){setError(cleanError(value));throw value;}finally{setBusy(false);}};
  const removeImage=async(item:CoupangQueueItem,imageUrl:string)=>{if(!account||!window.confirm('이 이미지를 발행 목록에서 삭제하시겠습니까?\n삭제한 이미지는 다시 추가할 수 없습니다.'))return;setBusy(true);setError('');try{const updated=await coupangQueueApi().removeImage({accountId:account.id,id:item.id,imageUrl,expectedUpdatedAt:item.updatedAt});setItems(current=>current.map(value=>value.id===updated.id?updated:value));setNotice(`발행 이미지가 ${updated.imageUrls.length}장으로 변경되었습니다.`);}catch(value){setError(cleanError(value));}finally{setBusy(false);}};
  const pageAction=<div className="dashboard-account-select"><label htmlFor="coupang-account">Threads 계정</label><select id="coupang-account" value={account?.id??''} onChange={event=>onSelectAccount(event.target.value)}>{snapshot.accounts.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button type="button" onClick={()=>void reloadQueue()}>새로고침</button></div>;
  if(!account)return <PageFrame title="쿠팡 파트너스" description="계정별 상품 선택, 분석·생성과 발행 전 목록을 관리합니다." action={pageAction}><section className="panel"><Empty text="계정 관리에서 Threads 계정을 먼저 등록하세요."/></section></PageFrame>;
  return <PageFrame title="쿠팡 파트너스" description="선택한 Threads 계정에 속한 상품만 검색하고 발행 준비합니다." action={pageAction}>
    <section className="account-context"><div><span className={`dot ${enabled?'success':'muted'}`}/><strong>{account.name}</strong><small>{account.threadsHandle?`@${account.threadsHandle.replace(/^@/,'')}`:'Threads 계정 미등록'}</small></div><span className={`badge ${enabled?'success':'warning'}`}>{enabled?(mode==='OPEN_API'?'최종 승인 완료':'최종 승인 전'):'쿠팡 파트너스 사용 안 함'}</span></section>
    {!enabled?<section className="panel"><Empty text="계정관리에서 이 계정의 쿠팡 파트너스 사용 여부와 운영 방식을 먼저 저장하세요."/></section>:<>
      {mode==='MANUAL_LINKS'?<section className="panel provider-coupang coupang-product-source"><header className="section-heading"><div><h2>쿠팡 파트너스 링크 등록</h2><p>직접 생성한 상품 링크를 분석해 이미지와 최종 본문까지 미리 저장합니다.</p></div></header><div className={`collector-status ${collectorStatus?.connected?'connected':collectorStatus?.hostRegistered?'waiting':'attention'}`}><span className="collector-status-icon" aria-hidden="true">{collectorStatus?.connected?'✓':'C'}</span><div><strong>{collectorStatus?.connected?'Chrome 수집기 연결됨':collectorStatus?.everConnected?'Chrome 수집기 연결 대기':'Chrome 수집기 설치 또는 연결 필요'}</strong><p>{collectorStatus?.message??'Chrome 수집기 상태를 확인하고 있습니다.'}</p>{collectorStatus?.connected&&<small>버전 {collectorStatus.extensionVersion??'-'} · 최근 연결 {fmtDate(collectorStatus.lastConnectedAt)}</small>}</div><div className="actions"><button type="button" onClick={()=>void refreshCollector(false)}>상태 새로고침</button>{!collectorStatus?.connected&&<button type="button" className="primary" onClick={()=>setCollectorPromptOpen(true)}>설치 안내</button>}</div></div><div className="coupang-manual-input"><Field label="상품 링크 · iframe 태그 · 블로그용 태그"><textarea rows={5} value={input} placeholder={'상품 링크, iframe 태그 또는 블로그용 태그를 붙여넣으세요.\n여러 상품 링크는 줄바꿈으로 구분할 수 있습니다.'} onChange={event=>setInput(event.target.value)}/></Field><div><p>등록 즉시 상품 페이지를 분석하고 Agent가 최종 발행 본문까지 생성합니다.</p><button type="button" className="primary" disabled={busy||!input.trim()||!collectorStatus?.connected} onClick={()=>void addManual()}>{busy?'분석·생성 중…':'자료 분석 후 등록'}</button></div></div></section>:<section className="panel provider-coupang coupang-product-source"><header className="section-heading"><div><h2>Open API 상품 선택</h2><p>저장된 계정별 키와 검색 조건으로 후보를 가져온 뒤 사용자가 직접 선택합니다.</p></div><button type="button" className="primary" onClick={()=>setSearchOpen(true)}>상품 검색</button></header><div className="coupang-filter-summary"><span><strong>키워드</strong>{searchSettings.keywords||'미설정'}</span>{searchSettings.keywordSearchIncluded&&<span>키워드 검색 포함</span>}{searchSettings.goldBoxIncluded&&<span>골드박스 포함 (키워드 무시)</span>}{searchSettings.categoryBestIncluded&&<span>카테고리 베스트 포함 · {searchSettings.categoryId==='ALL'?'전체':COUPANG_CATEGORY_OPTIONS.find(([id])=>id===searchSettings.categoryId)?.[1]}</span>}{searchSettings.coupangPlIncluded&&<span>쿠팡 파트너스 PL 포함 · {searchSettings.coupangPlBrandId==='ALL'?'전체':COUPANG_PL_BRAND_OPTIONS.find(([id])=>id===searchSettings.coupangPlBrandId)?.[1]}</span>}{searchSettings.rocketOnly&&<span>로켓배송만</span>}{searchSettings.rocketFreshOnly&&<span>로켓프레시 중심</span>}</div></section>}
      <div className="coupang-publication-flow"><strong>쿠팡 파트너스 단일 게시물 순서</strong><span>① 고지문</span><span>② 광고 본문</span><span>③ 상품 링크</span><span>④ 이미지 1~20장</span><small>발행 시점에는 이 화면에서 준비 완료된 저장본만 사용합니다.</small></div>
      <div className="coupang-queue-summary" aria-label="쿠팡 파트너스 자료 처리 현황"><span><small>대기</small><strong>{queueCounts.waiting}</strong></span><span><small>처리 중</small><strong>{queueCounts.processing}</strong></span><span><small>초안 완료</small><strong>{queueCounts.draft}</strong></span><span className={queueCounts.attention?'attention':''}><small>확인 필요</small><strong>{queueCounts.attention}</strong></span></div>
      {bulkCandidates.length>0&&<div className="coupang-bulk-actions"><label className="check"><input type="checkbox" checked={bulkCandidates.length>0&&bulkCandidates.slice(0,20).every((item)=>selectedQueueItems.has(item.id))} disabled={busy} onChange={event=>toggleAllQueueItems(event.target.checked)}/> 준비 대기 전체 선택</label><span><strong>{selectedQueueItems.size}</strong>/20개 선택</span><small>대기 상품만 일괄 처리합니다. 분석 완료 상품은 상세에서 건별로 재분석하세요.</small><button type="button" className="primary" disabled={busy||!selectedQueueItems.size} onClick={()=>void prepareSelected()}>{busy?'일괄 분석 중…':'선택 상품 일괄 분석·생성'}</button></div>}
      {notice&&<div className="notice" role="status">{notice}</div>}{error&&!searchOpen&&<div className="alert" role="alert">{error}</div>}
      <div className="coupang-queue-list" aria-live="polite">{busy&&!visibleItems.length?<div className="coupang-queue-empty">상품 자료를 처리하고 있습니다…</div>:visibleItems.length?visibleItems.map(item=>{const selectable=item.status==='QUEUED'||item.status==='INFORMATION_REQUIRED';return <CoupangQueueCard key={`${item.id}:${item.draftPostId??'no-draft'}:${item.updatedAt}`} item={item} busy={busy} selectable={selectable} selected={selectedQueueItems.has(item.id)} selectionFull={selectedQueueItems.size>=20} onSelect={toggleQueueItem} onPrepare={value=>void prepareItem(value)} onRetry={value=>void retryItem(value)} onDelete={value=>void deleteItem(value)} onSaveDraft={saveDraft} onRemoveImage={removeImage}/>;}):<div className="coupang-queue-empty">발행 전 상품 자료가 없습니다. 발행 완료 항목은 성과 리포트 &gt; 처리 현황에서 확인하세요.</div>}</div>
    </>}
    {collectorPromptOpen&&collectorStatus&&<ExtensionInstallGuide status={collectorStatus} onClose={()=>setCollectorPromptOpen(false)}/>}
    {searchOpen&&<div className="modal-backdrop" role="presentation"><section ref={searchDialogRef} className="modal coupang-search-modal" role="dialog" aria-modal="true" aria-labelledby="coupang-search-title">
      <header><div><h2 id="coupang-search-title">쿠팡 파트너스 상품 검색</h2><p>{account.name} 계정의 API 키로 검색합니다. 선택한 경로의 결과를 모두 포함합니다.</p></div><button type="button" className="icon-button" disabled={searchBusy} onClick={()=>setSearchOpen(false)} aria-label="닫기">×</button></header>
      <div className="modal-body"><div className="coupang-search-controls"><CoupangSearchOptions value={searchSettings} onChange={setSearchSettings}/><button type="button" className="primary" disabled={searchBusy||!hasCoupangProductSource(searchSettings)||(searchSettings.keywordSearchIncluded&&!searchSettings.keywords.trim())} onClick={()=>void runSearch()}>{searchBusy?'검색 중…':'상품 검색'}</button></div>
        {error&&<div className="alert" role="alert">{error}</div>}{searchMessage&&<div className="notice" role="status">{searchMessage}</div>}
        <div className="coupang-search-results">{searchResults.length?searchResults.map(candidate=>{const selected=selectedCandidates.has(candidate.id);return <label className={`coupang-search-result ${selected?'selected':''}`} key={candidate.id}><input type="checkbox" checked={selected} disabled={searchBusy} onChange={event=>toggleCandidate(candidate.id,event.target.checked)}/>{candidate.imageUrl?<img src={candidate.imageUrl} alt="" loading="lazy" referrerPolicy="no-referrer"/>:<span className="product-image-placeholder">이미지 없음</span>}<span><strong>{candidate.title}</strong><small>{fmtNumber(Number(candidate.metadata.price??0))}원</small><span className="source-chips">{candidate.metadata.isRocket===true&&<i className="badge">로켓배송</i>}{candidate.metadata.isRocketFresh===true&&<i className="badge success">로켓프레시</i>}{candidate.metadata.isGoldBox===true&&<i className="badge warning">골드박스</i>}{candidate.metadata.isCategoryBest===true&&<i className="badge">카테고리 베스트</i>}{candidate.metadata.isCoupangPl===true&&<i className="badge success">쿠팡 파트너스 PL</i>}</span></span></label>}):<div className="coupang-search-empty">검색 버튼을 누르면 상품 후보가 표시됩니다.</div>}</div>
      </div>
      <footer><SearchSelectionToggle ids={searchResults.map(item=>item.id)} selected={selectedCandidates} disabled={searchBusy} onChange={toggleAllCandidates}/><button type="button" disabled={searchBusy} onClick={()=>setSearchOpen(false)}>취소</button><button type="button" className="primary" disabled={searchBusy||!selectedCandidates.size} onClick={()=>void stageSelected()}>{searchBusy?'추가 중…':'선택 완료'}</button></footer>
    </section></div>}
  </PageFrame>;
}

function NaverBrandConnectProducts({snapshot,selectedAccountId,onSelectAccount,refresh}:{snapshot:AppSnapshot;selectedAccountId:string;onSelectAccount:(accountId:string)=>void;refresh:()=>Promise<void>}){
  const account=snapshot.accounts.find(item=>item.id===selectedAccountId)??snapshot.accounts[0];
  const accountId=account?.id;
  const [enabled,setEnabled]=useState(false);const [items,setItems]=useState<CoupangQueueItem[]>([]);const [input,setInput]=useState('');
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [collectorStatus,setCollectorStatus]=useState<CoupangCollectorStatus>();const [collectorPromptOpen,setCollectorPromptOpen]=useState(false);
  const load=async(id:string)=>{const [providers,queue,status]=await Promise.all([window.threadsAuto.providers.list(id),naverBrandQueueApi().list(id),window.threadsAuto.coupangCollector.status()]);setEnabled(Boolean(providers.find((entry:any)=>entry.type==='NAVER_BRAND_CONNECT')?.enabled));setItems(normalizeCoupangQueue(queue));setCollectorStatus(status);};
  useEffect(()=>{if(!accountId)return;let active=true;void Promise.all([window.threadsAuto.providers.list(accountId),naverBrandQueueApi().list(accountId),window.threadsAuto.coupangCollector.status()]).then(([providers,queue,status])=>{if(!active)return;setEnabled(Boolean(providers.find((entry:any)=>entry.type==='NAVER_BRAND_CONNECT')?.enabled));setItems(normalizeCoupangQueue(queue));setCollectorStatus(status);setError('');}).catch(value=>{if(active)setError(cleanError(value));});const off=window.threadsAuto.coupangCollector.onStatus(status=>{if(active)setCollectorStatus(status);});return()=>{active=false;off();};},[accountId]);
  const reloadQueue=async()=>{if(account)await load(account.id);};
  const refreshCollector=async(showPrompt=false)=>{const status=await window.threadsAuto.coupangCollector.status();setCollectorStatus(status);if(showPrompt&&!status.connected)setCollectorPromptOpen(true);};
  const addLinks=async()=>{if(!account||!input.trim())return;if(!collectorStatus?.connected){setError('Chrome 쇼핑 상품 수집기를 연결한 뒤 상품 자료를 분석하세요.');await refreshCollector(true);return;}setBusy(true);setError('');setNotice('');try{const result=await naverBrandQueueApi().add({accountId:account.id,text:input.trim()});setInput('');await reloadQueue();await refresh();setNotice(`네이버 상품 ${Array.isArray(result)?result.length:1}건의 이미지·후기와 최종 발행 본문을 저장했습니다.`);}catch(value){await reloadQueue().catch(()=>undefined);setError(cleanError(value));}finally{setBusy(false);}};
  const deleteItem=async(item:CoupangQueueItem)=>{if(!account||!window.confirm('이 네이버 브랜드 커넥트 상품 자료를 삭제하시겠습니까?'))return;setBusy(true);setError('');try{await naverBrandQueueApi().delete({accountId:account.id,id:item.id});await reloadQueue();await refresh();setNotice('상품 자료를 삭제했습니다.');}catch(value){setError(cleanError(value));}finally{setBusy(false);}};
  const prepareItem=async(item:CoupangQueueItem)=>{if(!account)return;setBusy(true);setError('');try{await naverBrandQueueApi().prepare({accountId:account.id,id:item.id});await reloadQueue();await refresh();setNotice('이미지·후기 분석과 최종 본문 생성을 완료했습니다.');}catch(value){setError(cleanError(value));await reloadQueue().catch(()=>undefined);}finally{setBusy(false);}};
  const retryItem=async(item:CoupangQueueItem)=>{if(!account)return;setBusy(true);setError('');try{await naverBrandQueueApi().retry({accountId:account.id,id:item.id});await reloadQueue();await refresh();setNotice('상품 페이지를 다시 조사하고 최종 본문을 새로 생성했습니다.');}catch(value){setError(cleanError(value));await reloadQueue().catch(()=>undefined);}finally{setBusy(false);}};
  const saveDraft=async(item:CoupangQueueItem,body:string)=>{if(!account)return;setBusy(true);setError('');try{const updated=await naverBrandQueueApi().updateDraft({accountId:account.id,id:item.id,body,expectedUpdatedAt:item.updatedAt});setItems(current=>current.map(value=>value.id===updated.id?updated:value));setNotice('네이버 브랜드 커넥트 최종 단일 본문을 저장했습니다.');}catch(value){setError(cleanError(value));throw value;}finally{setBusy(false);}};
  const removeImage=async(item:CoupangQueueItem,imageUrl:string)=>{if(!account||!window.confirm('이 이미지를 발행 목록에서 삭제하시겠습니까?\n삭제한 이미지는 다시 추가할 수 없습니다.'))return;setBusy(true);setError('');try{const updated=await naverBrandQueueApi().removeImage({accountId:account.id,id:item.id,imageUrl,expectedUpdatedAt:item.updatedAt});setItems(current=>current.map(value=>value.id===updated.id?updated:value));setNotice(`발행 이미지가 ${updated.imageUrls.length}장으로 변경되었습니다.`);}catch(value){setError(cleanError(value));}finally{setBusy(false);}};
  const counts={waiting:items.filter(item=>item.status==='QUEUED'||item.status==='INFORMATION_REQUIRED').length,processing:items.filter(item=>item.status==='PROCESSING').length,draft:items.filter(item=>item.status==='PREVIEW_READY').length,attention:items.filter(item=>item.status==='FAILED'||item.status==='REVIEW_REQUIRED').length};
  const pageAction=<div className="dashboard-account-select"><label htmlFor="naver-brand-account">Threads 계정</label><select id="naver-brand-account" value={account?.id??''} onChange={event=>onSelectAccount(event.target.value)}>{snapshot.accounts.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button type="button" disabled={!account||busy} onClick={()=>void reloadQueue()}>새로고침</button></div>;
  if(!account)return <PageFrame title="네이버 브랜드 커넥트" description="계정별 상품 링크, 분석 결과와 발행 전 목록을 관리합니다." action={pageAction}><section className="panel"><Empty text="계정 관리에서 Threads 계정을 먼저 등록하세요."/></section></PageFrame>;
  return <PageFrame title="네이버 브랜드 커넥트" description="사용자가 등록한 네이버 제휴 링크를 현재 Chrome에서 조사해 발행 준비합니다." action={pageAction}>
    <section className="account-context"><div><span className={`dot ${enabled?'success':'muted'}`}/><strong>{account.name}</strong><small>{account.threadsHandle?`@${account.threadsHandle.replace(/^@/,'')}`:'Threads 계정 미등록'}</small></div><span className={`badge ${enabled?'success':'warning'}`}>{enabled?'사용 중':'사용 안 함'}</span></section>
    {!enabled?<section className="panel provider-naver naver-brand-guidance"><header className="section-heading"><div><h2>네이버 브랜드 커넥트를 사용하지 않는 계정입니다.</h2><p>계정관리에서 ‘네이버 브랜드 커넥트’를 선택하고 이 계정 설정을 저장하면 상품 링크 등록과 대기열 관리가 활성화됩니다.</p></div></header></section>:<>
      <section className="panel provider-naver coupang-product-source"><header className="section-heading"><div><h2>네이버 브랜드 커넥트 링크 등록</h2><p>네이버에서 생성한 단축 제휴 링크를 줄마다 하나씩 넣으면 리다이렉트 완료 후 상품 페이지를 분석합니다.</p></div></header><div className={`collector-status ${collectorStatus?.connected?'connected':collectorStatus?.hostRegistered?'waiting':'attention'}`}><span className="collector-status-icon" aria-hidden="true">{collectorStatus?.connected?'✓':'N'}</span><div><strong>{collectorStatus?.connected?'Chrome 쇼핑 상품 수집기 연결됨':collectorStatus?.everConnected?'Chrome 쇼핑 상품 수집기 연결 대기':'Chrome 쇼핑 상품 수집기 설치 또는 연결 필요'}</strong><p>{collectorStatus?.message??'Chrome 수집기 상태를 확인하고 있습니다.'}</p>{collectorStatus?.connected&&<small>버전 {collectorStatus.extensionVersion??'-'} · 최근 연결 {fmtDate(collectorStatus.lastConnectedAt)}</small>}</div><div className="actions"><button type="button" onClick={()=>void refreshCollector(false)}>상태 새로고침</button>{!collectorStatus?.connected&&<button type="button" className="primary" onClick={()=>setCollectorPromptOpen(true)}>설치 안내</button>}</div></div><div className="coupang-manual-input"><Field label="네이버 브랜드 커넥트 제휴 링크"><textarea rows={5} value={input} placeholder={'https://naver.me/...\n여러 상품은 링크마다 줄을 바꿔 입력하세요.'} onChange={event=>setInput(event.target.value)}/></Field><div><p>등록 즉시 실제 도착 페이지의 상품명·갤러리·후기를 읽고 Agent가 최종 발행 본문까지 생성합니다.</p><button type="button" className="primary" disabled={busy||!input.trim()||!collectorStatus?.connected} onClick={()=>void addLinks()}>{busy?'리다이렉트·분석 중…':'자료 분석 후 등록'}</button></div></div></section>
      <div className="coupang-publication-flow provider-naver"><strong>네이버 브랜드 커넥트 단일 게시물 순서</strong><span>① 고지문</span><span>② 광고 본문</span><span>③ 제휴 링크</span><span>④ 이미지 1~20장</span><small>공식 고지 문구와 사용자가 등록한 원본 naver.me 링크를 유지합니다.</small></div>
      <div className="coupang-queue-summary" aria-label="네이버 상품 자료 처리 현황"><span><small>대기</small><strong>{counts.waiting}</strong></span><span><small>처리 중</small><strong>{counts.processing}</strong></span><span><small>초안 완료</small><strong>{counts.draft}</strong></span><span className={counts.attention?'attention':''}><small>확인 필요</small><strong>{counts.attention}</strong></span></div>
      {notice&&<div className="notice" role="status">{notice}</div>}{error&&<div className="alert" role="alert">{error}</div>}
      <div className="coupang-queue-list" aria-live="polite">{busy&&!items.length?<div className="coupang-queue-empty">리다이렉트된 상품 페이지를 분석하고 있습니다…</div>:items.length?items.map(item=><CoupangQueueCard key={`${item.id}:${item.draftPostId??'no-draft'}:${item.updatedAt}`} item={item} busy={busy} selectable={false} selected={false} selectionFull={false} onSelect={()=>undefined} onPrepare={value=>void prepareItem(value)} onRetry={value=>void retryItem(value)} onDelete={value=>void deleteItem(value)} onSaveDraft={saveDraft} onRemoveImage={removeImage}/>):<div className="coupang-queue-empty">발행 전 네이버 상품 자료가 없습니다. 위 입력란에 제휴 링크를 등록하세요.</div>}</div>
    </>}
    {collectorPromptOpen&&collectorStatus&&<ExtensionInstallGuide status={collectorStatus} onClose={()=>setCollectorPromptOpen(false)}/>}
  </PageFrame>;
}

function AppExecutionSettings({value,onSaved}:{value:AppSettings;onSaved:()=>Promise<void>}) {
  const [form,setForm]=useState(value);const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);
  const save=async()=>{setBusy(true);setMessage('');try{await window.threadsAuto.settings.save(form);setMessage('앱 설정을 저장했습니다.');await onSaved();}catch(e){setMessage(cleanError(e));}finally{setBusy(false);}};
  return <details className="panel app-execution-settings"><summary><div><strong>앱 실행 설정</strong><small>모델, Agent 제한 시간과 로그인 시 시작 옵션</small></div></summary><div className="app-settings-body">{message&&<div className="notice" aria-live="polite">{message}</div>}<div className="form-grid"><Field label="모델"><select value={form.codex.model} onChange={e=>setForm({...form,codex:{...form.codex,model:e.target.value}})}>{CODEX_MODEL_OPTIONS.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></Field><Field label="추론 수준"><select value={form.codex.reasoningEffort} onChange={e=>setForm({...form,codex:{...form.codex,reasoningEffort:e.target.value as any}})}>{REASONING_OPTIONS.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></Field><Field label="Agent 제한 시간(초)"><input type="number" min="30" max="1800" value={form.codex.timeoutSeconds} onChange={e=>setForm({...form,codex:{...form.codex,timeoutSeconds:Number(e.target.value)}})}/></Field></div><div className="check-stack"><label className="check"><input type="checkbox" checked={form.launchAtStartup} onChange={e=>setForm({...form,launchAtStartup:e.target.checked})}/> 컴퓨터 로그인 시 자동 실행</label></div><div className="settings-actions"><button className="primary" disabled={busy} onClick={()=>void save()}>{busy?'저장 중…':'앱 실행 설정 저장'}</button></div></div></details>;
}

function App(){const [page,setPage]=useState<Page>('dashboard');const [commentPostId,setCommentPostId]=useState<string>();const [selectedAccountId,setSelectedAccountId]=useState(()=>localStorage.getItem('threads-auto-account')??'');const [theme,setTheme]=useState<'light'|'dark'>(()=>localStorage.getItem('threads-auto-theme')==='dark'?'dark':'light');const [snapshot,setSnapshot]=useState<AppSnapshot>();const [liveEvents,setLiveEvents]=useState<LiveActivityEvent[]>([]);const [error,setError]=useState('');const refresh=async()=>{try{setSnapshot(await window.threadsAuto.snapshot());setError('');}catch(e){setError(cleanError(e));}};useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('threads-auto-theme',theme);},[theme]);useEffect(()=>{const load=()=>window.threadsAuto.snapshot().then(value=>{setSnapshot(value);setError('');}).catch(e=>setError(cleanError(e)));void load();const timer=setInterval(()=>void load(),15_000);const offUsage=window.threadsAuto.onUsage(usage=>setSnapshot(current=>current?{...current,dashboard:{...current.dashboard,usage}}:current));const offPipeline=window.threadsAuto.onPipeline(run=>{setSnapshot(current=>current?{...current,pipelineRuns:[run,...current.pipelineRuns.filter(item=>item.id!==run.id)].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,100)}:current);setLiveEvents(current=>appendLiveActivity(current,liveEventFromPipeline(run)));});const offJob=window.threadsAuto.onJob(activity=>setLiveEvents(current=>appendLiveActivity(current,liveEventFromJob(activity))));const offLog=window.threadsAuto.onLog(log=>{setLiveEvents(current=>appendLiveActivity(current,liveEventFromLog(log)));if(log.level==='WARN'||log.level==='ERROR')setSnapshot(current=>current?{...current,logs:[log,...current.logs.filter(item=>item.id!==log.id)].slice(0,200)}:current);});return()=>{clearInterval(timer);offUsage();offPipeline();offJob();offLog();};},[]);if(!snapshot)return <div className="loading" role="status">{error||'스레드 자동화를 준비하고 있습니다…'}</div>;
  const effectiveAccountId=snapshot.accounts.some(account=>account.id===selectedAccountId)?selectedAccountId:(snapshot.accounts[0]?.id??'');const selectAccount=(accountId:string)=>{setCommentPostId(undefined);setSelectedAccountId(accountId);localStorage.setItem('threads-auto-account',accountId);};const navigate=(next:Page)=>{setCommentPostId(undefined);setPage(next);};const openComments=(accountId:string,postId:string)=>{selectAccount(accountId);setCommentPostId(postId);setPage('comments');};const toggleTheme=()=>setTheme(current=>current==='light'?'dark':'light');
  return <div className="app-shell"><header className="titlebar"><img src={appIcon} alt=""/><strong>스레드 자동화</strong><span>by @복사장의생존발악</span><ExtensionInstallButton/></header><aside className="sidebar"><nav aria-label="주요 메뉴">{NAV.map(n=><button key={n.id} title={n.label} aria-label={n.label} aria-current={page===n.id?'page':undefined} className={page===n.id?'active':''} onClick={()=>navigate(n.id)}><span className="nav-icon">{n.icon}</span><span>{n.label}</span></button>)}</nav><div className="theme-area"><button className="theme-toggle" onClick={toggleTheme} aria-pressed={theme==='dark'} aria-label={`${theme==='light'?'다크':'라이트'} 모드로 전환`}><span>{theme==='light'?'◐':'☀'}</span><span>{theme==='light'?'다크 모드':'라이트 모드'}</span></button></div></aside><main><StatusBar snapshot={snapshot}/><div className="content">
    {page==='dashboard'&&<Dashboard snapshot={snapshot} selectedAccountId={effectiveAccountId} onSelectAccount={selectAccount} refresh={refresh} liveEvents={liveEvents}/>} {page==='coupang'&&<CoupangProducts snapshot={snapshot} selectedAccountId={effectiveAccountId} onSelectAccount={selectAccount} refresh={refresh}/>} {page==='naver-brand'&&<NaverBrandConnectProducts snapshot={snapshot} selectedAccountId={effectiveAccountId} onSelectAccount={selectAccount} refresh={refresh}/>} {page==='accounts'&&<Accounts accounts={snapshot.accounts} runtime={snapshot.accountRuntime} settings={snapshot.settings} selectedAccountId={effectiveAccountId} onSelectAccount={selectAccount} refresh={refresh}/>} {page==='comments'&&<Comments snapshot={snapshot} accountId={effectiveAccountId} onSelectAccount={selectAccount} postId={commentPostId} onClearPostFilter={()=>setCommentPostId(undefined)}/>} {page==='report'&&<Report key="report" snapshot={snapshot} refresh={refresh} onComments={openComments}/>} 
  </div></main></div>;
}

const rootElement=document.getElementById('root');
if(!rootElement)throw new Error('Threads Auto 화면 루트 요소를 찾을 수 없습니다.');
const rendererRuntime=window as typeof window&{__threadsAutoReactRoot?:ReturnType<typeof createRoot>};
const reactRoot=rendererRuntime.__threadsAutoReactRoot??createRoot(rootElement);
rendererRuntime.__threadsAutoReactRoot=reactRoot;
reactRoot.render(<React.StrictMode><App/></React.StrictMode>);
